@Override
		public void update() {
			// flashd is used locally to render the spike, and on the server for timing
			if(chargetime > 0) {
				flashd = 0;
			} else {
				flashd += 0.3f;
				flashd = Math.min(100.0f, flashd + 0.3f * (100.0f - flashd) * 0.15f);
			}

			if(!this.world.isRemote) {
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());

				if(chargetime == 1) {
					double x = (int) (this.pos.getX() + dir.offsetX * (this.world.getTotalWorldTime() / 5L) % 1) + 0.5;
					double y = (int) (this.pos.getY() + dir.offsetY * (this.world.getTotalWorldTime() / 5L) % 1) + 20.5;
					double z = (int) (this.pos.getZ() + dir.offsetZ * (this.world.getTotalWorldTime() / 5L) % 1) + 0.5;

					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "plasmablast");
					data.setFloat("r", 1F);
					data.setFloat("g", 1F);
					data.setFloat("b", 1F);
					data.setFloat("scale", 10 * 4);
					data.setFloat("yaw", 90);

					PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(data, x, y, z), new TargetPoint(this.world.provider.getDimension(), x, y, z, 256));
					this.world.playSoundEffect(x, y, z, "ambient.weather.thunder", 200, 0.8F + this.world.rand.nextFloat() * 0.2F);
					vapor();
				}

				// we only want to modify chargetime on the server, since it is synced to clients
				if(chargetime > 0) chargetime--;

				if(flashd >= 100) {
					chargetime = this.world.rand.nextInt(400) + 100;
				}

				PacketDispatcher.wrapper.sendToAllAround(new BufPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), this), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 256));
			}
		}

@Override
	public boolean onScrew(World world, EntityPlayer player, int x, int y, int z, int side, float fX, float fY, float fZ, ToolType tool) {

		if(tool != ToolType.DEFUSER)
			return false;

		TileEntityCharge charge = (TileEntityCharge) world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

		if(charge.started) {
			charge.started = !charge.started;
			world.playSoundEffect(x, y, z, "hbm:weapon.fstbmbStart", 1.0F, 1.0F);
			charge.markDirty();
		} else {
			safe = true;
			this.dismantle(world, x, y, z);
			safe = false;
		}

		return true;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(world.isRemote) {
			return true;
		} else {

			TileEntityCharge charge = (TileEntityCharge) world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

			if(!charge.started) {

				if(player.isSneaking()) {

					if(charge.timer > 0) {
						charge.started = true;
						world.playSoundEffect(x, y, z, "hbm:weapon.fstbmbStart", 1.0F, 1.0F);
					}
				} else {

					if(charge.timer == 0) { charge.timer = 100; }
					else if(charge.timer == 100) { charge.timer = 200; }
					else if(charge.timer == 200) { charge.timer = 300; }
					else if(charge.timer == 300) { charge.timer = 600; }
					else if(charge.timer == 600) { charge.timer = 1200; }
					else if(charge.timer == 1200) { charge.timer = 3600; }
					else if(charge.timer == 3600) { charge.timer = 6000; }
					else { charge.timer = 0; }

					world.playSoundEffect(x, y, z, "hbm:item.techBoop", 1.0F, 1.0F);
				}

				charge.markDirty();
			}

			return false;
		}
	}

