@Override
	public BombReturnCode explode(World world, int x, int y, int z) {
		world.playSoundEffect(x, y, z, "hbm:weapon.sparkShoot", 5.0f, world.rand.nextFloat() * 0.2F + 0.9F);

		if(!world.isRemote) {
			{ net.minecraft.world.World nativePlacementWorld = world; int nativePlacementX = x; int nativePlacementY = y; int nativePlacementZ = z; net.minecraft.block.Block nativePlacementBlock = Blocks.AIR; int nativePlacementMeta = 0; int nativePlacementFlags = 3; if (nativePlacementWorld == null) throw new NullPointerException(); if (nativePlacementX >= -30000000 && nativePlacementX < 30000000 && nativePlacementZ >= -30000000 && nativePlacementZ < 30000000 && nativePlacementY >= 0 && nativePlacementY < 256) nativePlacementWorld.setBlockState(new net.minecraft.util.math.BlockPos(nativePlacementX, nativePlacementY, nativePlacementZ), nativePlacementBlock.getStateFromMeta(nativePlacementMeta), nativePlacementFlags); }
			if(this == ModBlocks.float_bomb) {
				ExplosionChaos.floater(world, x, y, z, 15, 50);
				ExplosionChaos.move(world, x, y, z, 15, 0, 50, 0);
			}
			if(this == ModBlocks.emp_bomb) {
				ExplosionNukeGeneric.empBlast(world, x, y, z, 50);
				EntityEMPBlast wave = new EntityEMPBlast(world, 50);
				wave.posX = x + 0.5;
				wave.posY = y + 0.5;
				wave.posZ = z + 0.5;
				world.spawnEntityInWorld(wave);
			}
		}

		return BombReturnCode.DETONATED;
	}

public boolean igniteTestBomb(World world, int x, int y, int z) {
		if(!world.isRemote) {

			tetn.clearSlots();
			world.playSoundEffect(x, y, z, "random.explode", 1.0f, world.rand.nextFloat() * 0.1F + 0.9F);

			world.spawnEntityInWorld(EntityNukeExplosionMK5.statFac(world, BombConfig.boyRadius, x + 0.5, y + 0.5, z + 0.5));
			//world.spawnEntityInWorld(EntityNukeCloudSmall.statFac(world, x, y, z, BombConfig.boyRadius));

			EntityNukeTorex torex = new EntityNukeTorex(world);
			torex.setPositionAndRotation(x + 0.5, y + 1, z + 0.5, 0, 0);
			torex.getDataWatcher().updateObject(10, 1.5F);
			world.spawnEntityInWorld(torex);
			TrackerUtil.setTrackingRange(world, torex, 1000);
		}
		return false;
	}

public static void explodeCustom(World worldObj, double xCoord, double yCoord, double zCoord, float tnt, float nuke, float hydro, float amat, float dirty, float schrab, float euph) {

		dirty = Math.min(dirty, 100);

		/// EUPHEMIUM ///
		if(euph > 0) {

			EntityNukeExplosionMK3 ex = new EntityNukeExplosionMK3(worldObj);
			ex.posX = xCoord;
			ex.posY = yCoord;
			ex.posZ = zCoord;
			ex.destructionRange = 150;
			ex.speed = BombConfig.blastSpeed;
			ex.coefficient = 1.0F;
			ex.waste = false;
			worldObj.spawnEntityInWorld(ex);

			worldObj.playSoundEffect(xCoord, yCoord, zCoord, "random.explode", 100000.0F, 1.0F);

			EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(worldObj, 50);
			cloud.posX = xCoord;
			cloud.posY = yCoord;
			cloud.posZ = zCoord;
			worldObj.spawnEntityInWorld(cloud);

		// SCHRABIDIUM ///
		} else if(schrab > 0) {

			schrab += amat / 2 + hydro / 4 + nuke / 8 + tnt / 16;
			schrab = Math.min(schrab, maxSchrab);

			EntityNukeExplosionMK3 ex = EntityNukeExplosionMK3.statFacFleija(worldObj, xCoord + 0.5, yCoord + 0.5, zCoord + 0.5, (int) schrab);
			if(!ex.isDead) {
				worldObj.spawnEntityInWorld(ex);

				EntityCloudFleija cloud = new EntityCloudFleija(worldObj, (int) schrab);
				cloud.setPosition(xCoord + 0.5, yCoord + 0.5, zCoord + 0.5);
				worldObj.spawnEntityInWorld(cloud);
			}

    	/// ANTIMATTER ///
		} else if(amat > 0) {

			amat += hydro / 2 + nuke / 4 + tnt / 8;
			amat = Math.min(amat, maxAmat);

			EntityBalefire bf = new EntityBalefire(worldObj);
			bf.antimatter();
    		bf.setPosition(xCoord + 0.5, yCoord + 0.5, zCoord + 0.5);
			bf.destructionRange = (int) amat;
			worldObj.spawnEntityInWorld(bf);
			EntityNukeTorex.startFacAnti(worldObj, xCoord + 0.5, yCoord + 5, zCoord + 0.5, amat);

		/// HYDROGEN ///
		} else if(hydro > 0) {

			hydro += nuke / 2 + tnt / 4;
			hydro = Math.min(hydro, maxHydro);
			dirty *= 0.25F;

			worldObj.spawnEntityInWorld(EntityNukeExplosionMK5.statFac(worldObj, (int)hydro, xCoord + 0.5, yCoord + 0.5, zCoord + 0.5).moreFallout((int)dirty));
			EntityNukeTorex.statFacStandard(worldObj, xCoord + 0.5, yCoord + 5, zCoord + 0.5, hydro);

		/// NUCLEAR ///
		} else if(nuke > 0) {

			nuke += tnt / 2;
			nuke = Math.min(nuke, maxNuke);

			worldObj.spawnEntityInWorld(EntityNukeExplosionMK5.statFac(worldObj, (int)nuke, xCoord + 0.5, yCoord + 5, zCoord + 0.5).moreFallout((int)dirty));
			EntityNukeTorex.statFacStandard(worldObj, xCoord + 0.5, yCoord + 5, zCoord + 0.5, nuke);

		/// NON-NUCLEAR ///
		} else if(tnt >= 75) {

			tnt = Math.min(tnt, maxTnt);

			worldObj.spawnEntityInWorld(EntityNukeExplosionMK5.statFacNoRad(worldObj, (int)tnt, xCoord + 0.5, yCoord + 0.5, zCoord + 0.5));
			EntityNukeTorex.statFacStandard(worldObj, xCoord + 0.5, yCoord + 5, zCoord + 0.5, tnt);
		} else if(tnt > 0) {

			ExplosionLarge.explode(worldObj, xCoord + 0.5, yCoord + 0.5, zCoord + 0.5, tnt, true, true, true);
		}
	}

public boolean igniteTestBomb(World world, int x, int y, int z, int r) {
