				world.playSoundEffect(x, y, z, "random.explode", 1.0f, world.rand.nextFloat() * 0.1F + 0.9F);
				world.spawnEntityInWorld(ex);

				EntityCloudFleija cloud = new EntityCloudFleija(world, r);
				cloud.posX = x;
				cloud.posY = y;
				cloud.posZ = z;
				world.spawnEntityInWorld(cloud);
			}
		}

		return false;
	}

