@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		TileEntityPlushie plushie = (TileEntityPlushie) world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

		if(world.isRemote) {
			plushie.squishTimer = 11;
			return true;
		} else {
			if(plushie != null) {
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, plushie.type.sound, 0.25F, 1F);
			}
			return true;
		}
	}

@Override
	public void updateTick(World world, int x, int y, int z, Random rand) {
		if(this == ModBlocks.block_meteor_molten) {
			if(!world.isRemote)
				world.setBlock(x, y, z, ModBlocks.block_meteor_cobble);
			world.playSoundEffect((double) ((float) x + 0.5F), (double) ((float) y + 0.5F), (double) ((float) z + 0.5F), "random.fizz", 0.5F, 2.6F + (world.rand.nextFloat() - world.rand.nextFloat()) * 0.8F);
			return;
		}
	}

@SuppressWarnings("incomplete-switch")
	@Override
	public void onEntityWalking(World world, int x, int y, int z, Entity entity) {

    	int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );

    	if(world.isRemote || Trap.get(meta).type != TrapType.ON_STEP || !(entity instanceof EntityPlayer)) {
    		return;
    	}

    	EntityPlayer player = (EntityPlayer)entity;

		switch(Trap.get(meta)) {
		case FIRE:
			if(com.hbm.world.WorldBlockState.read(world, x, y + 1, z).getBlock().isReplaceable(world, x, y + 1, z))
				{ net.minecraft.world.World nativePlacementWorld = world; int nativePlacementX = x; int nativePlacementY = y + 1; int nativePlacementZ = z; net.minecraft.block.Block nativePlacementBlock = Blocks.FIRE; int nativePlacementMeta = 0; int nativePlacementFlags = 3; if (nativePlacementWorld == null) throw new NullPointerException(); if (nativePlacementX >= -30000000 && nativePlacementX < 30000000 && nativePlacementZ >= -30000000 && nativePlacementZ < 30000000 && nativePlacementY >= 0 && nativePlacementY < 256) nativePlacementWorld.setBlockState(new net.minecraft.util.math.BlockPos(nativePlacementX, nativePlacementY, nativePlacementZ), nativePlacementBlock.getStateFromMeta(nativePlacementMeta), nativePlacementFlags); }
			break;
		case SPIKES:
			if(com.hbm.world.WorldBlockState.read(world, x, y + 1, z).getBlock().isReplaceable(world, x, y + 1, z))
				world.setBlock(x, y + 1, z, ModBlocks.spikes);
			List<Entity> targets = world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(x, y + 1, z, x + 1, y + 2, z + 1));
			for(Entity e : targets)
				e.attackEntityFrom(ModDamageSource.spikes, 10);
			world.playSoundEffect(x + 0.5, y + 1.5, z + 0.5, "hbm:entity.slicer", 1.0F, 1.0F);
			break;
		case MINE:
			world.createExplosion(null, x + 0.5, y + 1.5, z + 0.5, 1F, false);
			break;
		case WEB:
			if(com.hbm.world.WorldBlockState.read(world, x, y + 1, z).getBlock().isReplaceable(world, x, y + 1, z))
				{ net.minecraft.world.World nativePlacementWorld = world; int nativePlacementX = x; int nativePlacementY = y + 1; int nativePlacementZ = z; net.minecraft.block.Block nativePlacementBlock = Blocks.WEB; int nativePlacementMeta = 0; int nativePlacementFlags = 3; if (nativePlacementWorld == null) throw new NullPointerException(); if (nativePlacementX >= -30000000 && nativePlacementX < 30000000 && nativePlacementZ >= -30000000 && nativePlacementZ < 30000000 && nativePlacementY >= 0 && nativePlacementY < 256) nativePlacementWorld.setBlockState(new net.minecraft.util.math.BlockPos(nativePlacementX, nativePlacementY, nativePlacementZ), nativePlacementBlock.getStateFromMeta(nativePlacementMeta), nativePlacementFlags); }
			break;
		case RAD_CONVERSION:
			for(int a = - 3; a <= 3; a++) {
				for(int b = - 3; b <= 3; b++) {
					for(int c = - 3; c <= 3; c++) {

						if(world.rand.nextBoolean())
							continue;

						Block bl = com.hbm.world.WorldBlockState.read(world, x + a, y + b, z + c).getBlock();
						if(bl == ModBlocks.brick_jungle || bl == ModBlocks.brick_jungle_cracked || bl == ModBlocks.brick_jungle_lava) {
							world.setBlock(x + a, y + b, z + c, ModBlocks.brick_jungle_ooze);
						}
					}
				}
			}
			break;
		case MAGIC_CONVERSTION:
			for(int a = - 3; a <= 3; a++) {
				for(int b = - 3; b <= 3; b++) {
					for(int c = - 3; c <= 3; c++) {

						if(world.rand.nextBoolean())
							continue;

						Block bl = com.hbm.world.WorldBlockState.read(world, x + a, y + b, z + c).getBlock();
						if(bl == ModBlocks.brick_jungle || bl == ModBlocks.brick_jungle_cracked || bl == ModBlocks.brick_jungle_lava) {
							world.setBlock(x + a, y + b, z + c, ModBlocks.brick_jungle_mystic);
						}
					}
				}
			}
			break;
		case SLOWNESS:
			player.addPotionEffect(new PotionEffect(Potion.moveSlowdown.id, 300, 2));
			break;
		case WEAKNESS:
			player.addPotionEffect(new PotionEffect(Potion.weakness.id, 300, 2));
			break;
		}

		world.playSoundEffect(x + 0.5D, y + 0.5D, z + 0.5D, "random.click", 0.3F, 0.6F);
		world.setBlock(x, y, z, ModBlocks.brick_jungle);
    }

@SuppressWarnings("incomplete-switch")
	@Override
	public void onEntityWalking(World world, int x, int y, int z, Entity entity) {

    	int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );

    	if(world.isRemote || Trap.get(meta).type != TrapType.ON_STEP || !(entity instanceof EntityPlayer)) {
    		return;
    	}

    	EntityPlayer player = (EntityPlayer)entity;

		switch(Trap.get(meta)) {
		case FIRE:
			if(com.hbm.world.WorldBlockState.read(world, x, y + 1, z).getBlock().isReplaceable(world, x, y + 1, z))
				{ net.minecraft.world.World nativePlacementWorld = world; int nativePlacementX = x; int nativePlacementY = y + 1; int nativePlacementZ = z; net.minecraft.block.Block nativePlacementBlock = Blocks.FIRE; int nativePlacementMeta = 0; int nativePlacementFlags = 3; if (nativePlacementWorld == null) throw new NullPointerException(); if (nativePlacementX >= -30000000 && nativePlacementX < 30000000 && nativePlacementZ >= -30000000 && nativePlacementZ < 30000000 && nativePlacementY >= 0 && nativePlacementY < 256) nativePlacementWorld.setBlockState(new net.minecraft.util.math.BlockPos(nativePlacementX, nativePlacementY, nativePlacementZ), nativePlacementBlock.getStateFromMeta(nativePlacementMeta), nativePlacementFlags); }
			break;
		case SPIKES:
			if(com.hbm.world.WorldBlockState.read(world, x, y + 1, z).getBlock().isReplaceable(world, x, y + 1, z))
				world.setBlock(x, y + 1, z, ModBlocks.spikes);
			List<Entity> targets = world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(x, y + 1, z, x + 1, y + 2, z + 1));
			for(Entity e : targets)
				e.attackEntityFrom(ModDamageSource.spikes, 10);
			world.playSoundEffect(x + 0.5, y + 1.5, z + 0.5, "hbm:entity.slicer", 1.0F, 1.0F);
			break;
		case MINE:
			world.createExplosion(null, x + 0.5, y + 1.5, z + 0.5, 1F, false);
			break;
		case WEB:
			if(com.hbm.world.WorldBlockState.read(world, x, y + 1, z).getBlock().isReplaceable(world, x, y + 1, z))
				{ net.minecraft.world.World nativePlacementWorld = world; int nativePlacementX = x; int nativePlacementY = y + 1; int nativePlacementZ = z; net.minecraft.block.Block nativePlacementBlock = Blocks.WEB; int nativePlacementMeta = 0; int nativePlacementFlags = 3; if (nativePlacementWorld == null) throw new NullPointerException(); if (nativePlacementX >= -30000000 && nativePlacementX < 30000000 && nativePlacementZ >= -30000000 && nativePlacementZ < 30000000 && nativePlacementY >= 0 && nativePlacementY < 256) nativePlacementWorld.setBlockState(new net.minecraft.util.math.BlockPos(nativePlacementX, nativePlacementY, nativePlacementZ), nativePlacementBlock.getStateFromMeta(nativePlacementMeta), nativePlacementFlags); }
			break;
		case RAD_CONVERSION:
			for(int a = - 3; a <= 3; a++) {
				for(int b = - 3; b <= 3; b++) {
					for(int c = - 3; c <= 3; c++) {

						if(world.rand.nextBoolean())
							continue;

						Block bl = com.hbm.world.WorldBlockState.read(world, x + a, y + b, z + c).getBlock();
						if(bl == ModBlocks.brick_jungle || bl == ModBlocks.brick_jungle_cracked || bl == ModBlocks.brick_jungle_lava) {
							world.setBlock(x + a, y + b, z + c, ModBlocks.brick_jungle_ooze);
						}
					}
				}
			}
			break;
		case MAGIC_CONVERSTION:
			for(int a = - 3; a <= 3; a++) {
				for(int b = - 3; b <= 3; b++) {
					for(int c = - 3; c <= 3; c++) {

						if(world.rand.nextBoolean())
							continue;

						Block bl = com.hbm.world.WorldBlockState.read(world, x + a, y + b, z + c).getBlock();
						if(bl == ModBlocks.brick_jungle || bl == ModBlocks.brick_jungle_cracked || bl == ModBlocks.brick_jungle_lava) {
							world.setBlock(x + a, y + b, z + c, ModBlocks.brick_jungle_mystic);
						}
					}
				}
			}
			break;
		case SLOWNESS:
			player.addPotionEffect(new PotionEffect(Potion.moveSlowdown.id, 300, 2));
			break;
		case WEAKNESS:
			player.addPotionEffect(new PotionEffect(Potion.weakness.id, 300, 2));
			break;
		}

		world.playSoundEffect(x + 0.5D, y + 0.5D, z + 0.5D, "random.click", 0.3F, 0.6F);
		world.setBlock(x, y, z, ModBlocks.brick_jungle);
    }

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(!CelestialBody.inOrbit(world)) return false;

		if(world.isRemote) {
			return true;
		} else {
			int[] pos = this.findCore(world, x, y, z);

			if(pos == null)
				return false;

			TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));

			if(!(te instanceof TileEntityOrbitalStationComputer))
				return false;

			TileEntityOrbitalStationComputer computer = (TileEntityOrbitalStationComputer) te;

			if(computer.isTravelling())
				return false;

			ItemStack heldStack = com.hbm.util.NativeHeldItem.getMainHandNullable(player);

			if(heldStack != null && heldStack.getItem() instanceof ItemVOTVdrive) {
				if(computer.slots[0] != null)
					return false;

				Destination destination = ItemVOTVdrive.getDestination(heldStack);

				if(destination.body == SolarSystem.Body.ORBIT)
					return false;

				if(computer.travelTo(destination.body.getBody(), heldStack.copy())) {
					heldStack.stackSize = 0;
					world.playSoundEffect(x, y, z, "hbm:item.upgradePlug", 1.0F, 1.0F);
				} else {
					return false;
				}
			} else if(heldStack == null && computer.slots[0] != null) {
				if(!player.inventory.addItemStackToInventory(computer.slots[0].copy())) {
					player.dropPlayerItemWithRandomChoice(computer.slots[0].copy(), false);
				}
				computer.slots[0] = null;
				computer.markChanged();
			} else {
				FMLNetworkHandler.openGui(player, MainRegistry.instance, 0, world, pos[0], pos[1], pos[2]);
			}


			return true;
		}
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(world.isRemote) {
			return true;
		} else {

			int[] pos = this.findCore(world, x, y, z);

			if(pos == null)
				return false;

			TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));

			if(!(te instanceof TileEntityConveyorPress))
				return false;

			TileEntityConveyorPress press = (TileEntityConveyorPress) te;

			if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() instanceof ItemStamp && press.slots[0] == null) {
				press.slots[0] = com.hbm.util.NativeHeldItem.getMainHandNullable(player).copy();
				press.slots[0].setCount(1);
				com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.0F, 1.0F);
				press.markChanged();
				world.markBlockForUpdate(x, y, z);
				return true;
			}
		}

		return false;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(world.isRemote)
		{
			return true;
		} else if(!player.isSneaking())
		{
			int[] pos = this.findCore(world, x, y, z);

			if(pos == null)
				return false;

			TileEntityMachineCyclotron cyc = (TileEntityMachineCyclotron)world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));

			if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null) {

				for(int i = 0; i < 4; i++) {

					if(com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == TileEntityMachineCyclotron.getItemForPlug(i) && !cyc.getPlug(i)) {
						com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
						cyc.setPlug(i);
						world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.5F, 1.0F);
						return true;
					}
				}
			}

			FMLNetworkHandler.openGui(player, MainRegistry.instance, 0, world, pos[0], pos[1], pos[2]);
			return true;
		} else {
			return false;
		}
	}

