@Override
	public boolean onScrew(World world, EntityPlayer player, int x, int y, int z, int side, float fX, float fY, float fZ, ToolType tool) {
		if(tool == ToolType.SCREWDRIVER) {
			int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );

			if(meta == 0) world.setBlockMetadataWithNotify(x, y, z, 1, 3);
			if(meta == 1) world.setBlockMetadataWithNotify(x, y, z, 0, 3);
			if(meta == 2) world.setBlockMetadataWithNotify(x, y, z, 3, 3);
			if(meta == 3) world.setBlockMetadataWithNotify(x, y, z, 2, 3);
			if(meta == 4) world.setBlockMetadataWithNotify(x, y, z, 5, 3);
			if(meta == 5) world.setBlockMetadataWithNotify(x, y, z, 4, 3);

			return true;
		}

		if(tool == ToolType.HAND_DRILL) {
			TileEntityFan tile = (TileEntityFan) world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

			if(tile != null) {
				tile.falloff = !tile.falloff;
				tile.markDirty();

				if(!world.isRemote) {
					PacketDispatcher.wrapper.sendTo(new PlayerInformPacket(ChatBuilder.start("").nextTranslation(this.getTranslationKey() + (tile.falloff ? ".falloffOn" : ".falloffOff")).color(TextFormatting.GOLD).flush(), MainRegistry.proxy.ID_FAN_MODE), (EntityPlayerMP) player);

					world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "random.click", 0.5F, 0.5F);
				}
			}

			return true;
		}

		return false;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {

		if(world.isRemote) {
			return true;

		} else if(!player.isSneaking()) {
			int[] pos = this.findCore(world, x, y, z);

			if(pos == null)
				return false;

			TileEntitySawmill sawmill = (TileEntitySawmill)world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));

			if(!sawmill.hasBlade && com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == ModItems.sawblade) {
				com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
				sawmill.hasBlade = true;
				sawmill.markDirty();
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.5F, 0.75F);
				return true;
			}

			if(sawmill.slots[1] != null || sawmill.slots[2] != null) {
				for(int i = 1; i < 3; i++) {
					if(sawmill.slots[i] != null) {
						if(!player.inventory.addItemStackToInventory(sawmill.slots[i].copy())) {
							player.dropPlayerItemWithRandomChoice(sawmill.slots[i].copy(), false);
						}
						sawmill.slots[i] = null;
					}
				}
				player.inventoryContainer.detectAndSendChanges();
				sawmill.markDirty();
				return true;

			} else {
				if(sawmill.slots[0] == null && com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && sawmill.getOutput(com.hbm.util.NativeHeldItem.getMainHandNullable(player)) != null) {
					sawmill.slots[0] = com.hbm.util.NativeHeldItem.getMainHandNullable(player).copy();
					sawmill.slots[0].setCount(1);
					com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
					sawmill.markDirty();
					player.inventoryContainer.detectAndSendChanges();
					return true;
				}
			}
		}

		return false;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {

		if(world.isRemote) {
			return true;

		} else if(!player.isSneaking()) {
			int[] pos = this.findCore(world, x, y, z);

			if(pos == null)
				return false;

			TileEntityStirling stirling = (TileEntityStirling)world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));
			int meta = stirling.getGeatMeta();

			if(!stirling.hasCog && com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == ModItems.gear_large && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItemDamage() == meta) {
				com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
				stirling.hasCog = true;
				stirling.markDirty();
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.5F, 0.75F);
				return true;
			}
		}

		return false;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(world.isRemote) {
			return true;
		}

		int[] coords = findCore(world, x, y, z);
		TileEntityMachineStrandCaster cast = (TileEntityMachineStrandCaster) world.getTileEntity(new net.minecraft.util.math.BlockPos(coords[0], coords[1], coords[2]));
		if(cast != null) {
			// insert mold
			if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == ModItems.mold && cast.slots[0] == null) {
				cast.slots[0] = com.hbm.util.NativeHeldItem.getMainHandNullable(player).copy();
				cast.slots[0].setCount(1);
				com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.0F, 1.0F);
				cast.markDirty();
				return true;

			}

			if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() instanceof ItemTool && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem().getToolClasses(com.hbm.util.NativeHeldItem.getMainHandNullable(player)).contains("shovel")) {
				if(cast.amount > 0) {
					ItemStack scrap = ItemScraps.create(new Mats.MaterialStack(cast.type, cast.amount));
					if(!player.inventory.addItemStackToInventory(scrap)) {
						EntityItem item = new EntityItem(world, x + 0.5, y + this.maxY, z + 0.5, scrap);
						world.spawnEntityInWorld(item);
					} else {
						player.inventoryContainer.detectAndSendChanges();
					}
					cast.amount = 0;
					cast.type = null;
					cast.markDirty();
				}
				return true;
			}
		}
		return this.standardOpenBehavior(world, x, y, z, player, 0);
	}

@Override
		public void update() {

			if(!this.world.isRemote) {

				if(delay <= 0) {

					if(this.isRetracting && this.extend > 0) {
						this.extend--;
					} else if(!this.isRetracting) {
						this.extend++;

						if(this.extend >= this.maxExtend) {
							this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.pressOperate", 1.0F, 1.5F);

							ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());
							Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + dir.offsetX * 2, this.pos.getY() + dir.offsetY * 2, this.pos.getZ() + dir.offsetZ * 2).getBlock();

							if(b instanceof IInsertable && ((IInsertable) b).insertItem(this.world, this.pos.getX() + dir.offsetX * 2, this.pos.getY() + dir.offsetY * 2, this.pos.getZ() + dir.offsetZ * 2, dir, slot)) {
								this.decrStackSize(0, 1);
							}

							this.isRetracting = true;
							this.delay = 5;
						}
					}

				} else {
					delay--;
				}

				networkPackNT(25);

			} else {
				this.lastExtend = this.renderExtend;

				if(this.turnProgress > 0) {
					this.renderExtend += (this.syncExtend - this.renderExtend) / (double) this.turnProgress;
					this.turnProgress--;
				} else {
					this.renderExtend = this.syncExtend;
				}
			}

		}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(world.isRemote) {
			return true;
		} else if(!player.isSneaking()) {
			TileEntityRadiobox box = (TileEntityRadiobox)world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

			if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == ModItems.battery_spark && !box.infinite) {
				com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
