public void onBlockAdded(World world, int x, int y, int z) {
		super.onBlockAdded(world, x, y, z);

		if(!world.isRemote) {
			if(world.rand.nextInt(4) == 0) {
				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "rbmkflame");
				data.setInteger("maxAge", 90);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, x + 0.25 + world.rand.nextDouble() * 0.5, y + 1.75, z + 0.25 + world.rand.nextDouble() * 0.5), new TargetPoint(world.provider.getDimension(), x + 0.5, y + 1.75, z + 0.5, 75));
				MainRegistry.proxy.effectNT(data);
				world.playSoundEffect(x + 0.5F, y + 0.5, z + 0.5, "fire.fire", 1.0F + world.rand.nextFloat(), world.rand.nextFloat() * 0.7F + 0.3F);
			}
		}

		world.scheduleBlockUpdate(x, y, z, this, this.tickRate(world));
	}

@Override
	public boolean onScrew(World world, EntityPlayer player, int x, int y, int z, int side, float fX, float fY, float fZ, ToolType tool) {

		if(tool != ToolType.HAND_DRILL)
			return false;

		if(!world.isRemote) {
			world.setBlock(x, y, z, ModBlocks.block_graphite_drilled, side / 2, 3);
			PacketDispatcher.wrapper.sendToAllAround(new ParticleBurstPacket(x, y, z, Block.getIdFromBlock(this), 0), new TargetPoint(world.provider.getDimension(), x, y, z, 50));
			world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, this.stepSound.func_150496_b(), (this.stepSound.getVolume() + 1.0F) / 2.0F, this.stepSound.getPitch() * 0.8F);

			BlockGraphiteRod.ejectItem(world, x, y, z, ForgeDirection.getOrientation(side), new ItemStack(ModItems.ingot_graphite));
		}

		return true;
	}

private boolean checkInteraction(World world, int x, int y, int z, int meta, EntityPlayer player, Item item, Block block) {

		if(com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == item) {

			if(item == ModItems.shell && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItemDamage() != Mats.MAT_ALUMINIUM.id) return false; //shitty workaround

			com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
			world.setBlock(x, y, z, block, meta, 3);

			world.playSoundEffect(x + 0.5, y + 1.5, z + 0.5, "hbm:item.upgradePlug", 1.0F, 1.0F);

			return true;
		}

		return false;
	}

@Override
	public boolean onScrew(World world, EntityPlayer player, int x, int y, int z, int side, float fX, float fY, float fZ, ToolType tool) {

		int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );
		int cfg = meta & 3;

		if(tool != ToolType.SCREWDRIVER)
			return false;

		if(!world.isRemote && (side == cfg * 2 || side == cfg * 2 + 1) && meta >> 2 == 1) {
			world.setBlock(x, y, z, ModBlocks.block_graphite_drilled, cfg, 3);
			world.playSoundEffect(x + 0.5, y + 1.5, z + 0.5, "hbm:item.upgradePlug", 1.0F, 0.85F);

			BlockGraphiteRod.ejectItem(world, x, y, z, ForgeDirection.getOrientation(side), new ItemStack(ModItems.shell, 1, Mats.MAT_ALUMINIUM.id));
		}

		return true;
	}

@Override
	public boolean insertItem(World world, int x, int y, int z, ForgeDirection dir, ItemStack stack) {

		if(stack == null) return false;

		MetaBlock baseBlock = checkInteractions(stack);
		if(baseBlock == null) return false;

		final int side = dir.ordinal();
		final int pureMeta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) ) & 3; //in case it's shrouded in aluminum

		if(side == pureMeta * 2 || side == pureMeta * 2 + 1) {
			//first, make sure we can even push rods out
			for(int i = 0; i <= 3; i++) { //limited to 3 boyos
				int ix = x + dir.offsetX * i;
				int iy = y + dir.offsetY * i;
				int iz = z + dir.offsetZ * i;

				Block b = com.hbm.world.WorldBlockState.read(world, ix, iy, iz).getBlock();

				if(b instanceof BlockGraphiteDrilledBase) {
					int baseMeta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, ix, iy, iz) );
					if((baseMeta & 3) != pureMeta) //wrong orientation
						return false;

					if(((BlockGraphiteDrilledBase)b).getInsertedItem(baseMeta) == null) //if there's nothing to push
						break;
					else if(i >= 3) //if there is stuff to push and we reach our limit
						return false;
				} else {
					if(b.isNormalCube()) //obstructions
						return false;
					else //empty space? no need to search
						break;
				}
			}

			//TODO convert old methods to use itemstack for flexibility
			int oldMeta = pureMeta | baseBlock.meta; //metablocks are kinda inconvenient to work with so 
			Block oldBlock = baseBlock.block;
			NBTTagCompound oldTag = new NBTTagCompound(); //In case of TEs
			oldTag.setInteger("x", x); //giving tags prevents issues and resets any lingering tes.
			oldTag.setInteger("y", y);
			oldTag.setInteger("z", z);

			//now actually make the change
			for(int i = 0; i <= 3; i++) { //yeah yeah we know it's safe but let's be *extra cautious* of infinite loops
				int ix = x + dir.offsetX * i;
				int iy = y + dir.offsetY * i;
				int iz = z + dir.offsetZ * i;

				Block newBlock = com.hbm.world.WorldBlockState.read(world, ix, iy, iz).getBlock();

				if(newBlock instanceof BlockGraphiteDrilledBase) {
					int newMeta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, ix, iy, iz) );
					NBTTagCompound newTag = new NBTTagCompound();

					if(newBlock instanceof BlockGraphiteDrilledTE) {
						TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(ix, iy, iz));
						te.writeToNBT(newTag);
						newTag.setInteger("x", te.getPos().getX() + dir.offsetX); //malformed positions is very very bad and prevents the pile TEs from ticking
						newTag.setInteger("y", te.getPos().getY() + dir.offsetY);
						newTag.setInteger("z", te.getPos().getZ() + dir.offsetZ);
					}

					world.setBlock(ix, iy, iz, oldBlock, (oldMeta & ~0b100) | (newMeta & 0b100), 0);

					if(oldBlock instanceof BlockGraphiteDrilledTE && !oldTag.hasNoTags()) { //safety first
						TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(ix, iy, iz));
						te.readFromNBT(oldTag);
					}

					world.markAndNotifyBlock(ix, iy, iz, world.getChunkFromBlockCoords(ix, iz), newBlock, oldBlock, 3); //in case setBlock returns false due to = meta / block

					oldMeta = newMeta;
					oldBlock = newBlock;
					oldTag = newTag;

					if(oldBlock instanceof BlockGraphiteDrilled) //if there's no need to eject an item
						break;
				} else {
					Item eject = ((BlockGraphiteDrilledBase) oldBlock).getInsertedItem(oldMeta); //TODO old methods to itemstack
					this.ejectItem(world, ix - dir.offsetX, iy - dir.offsetY, iz - dir.offsetZ, dir, new ItemStack(eject));
					world.playSoundEffect(ix + 0.5, iy + 0.5, iz + 0.5, "hbm:item.upgradePlug", 1.25F, 1.0F);

					break;
				}
			}

			return true;
		}

		return false;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {

		if(player.isSneaking())
			return false;

		int oldMeta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );
		int newMeta = oldMeta ^ 8; //toggle bit #4
		int pureMeta = oldMeta & 3; //in case the bit was set

		if(side == pureMeta * 2 || side == pureMeta * 2 + 1) {

			if(world.isRemote)
				return true;

			world.setBlockMetadataWithNotify(x, y, z, newMeta, 3);

			world.playSoundEffect(x + 0.5D, y + 0.5D, z + 0.5D, "random.click", 0.3F, pureMeta == (oldMeta & 11) ? 0.75F : 0.65F);

			ForgeDirection dir = ForgeDirection.getOrientation(side);

			if(dir == ForgeDirection.UNKNOWN)
				return true;

			for(int i = -1; i <= 1; i += 1) {

				//why is XZ switched? i don't know, man
				/* ForgeDirection's getOrientation method operates on actual sides, not n/s or w/e, so you had to switch x & z for w/e to work since it was actually returning north. also meant that
				 n/s hasn't been working this entire time */
				int ix = x + dir.offsetX * i;
				int iy = y + dir.offsetY * i;
				int iz = z + dir.offsetZ * i;

				while(com.hbm.world.WorldBlockState.read(world, ix, iy, iz).getBlock() == this && com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, ix, iy, iz) ) == oldMeta) {

					world.setBlockMetadataWithNotify(ix, iy, iz, newMeta, 3);

					ix += dir.offsetX * i;
					iy += dir.offsetY * i;
					iz += dir.offsetZ * i;
				}
			}

			return true;
		}

		return false;
	}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		BossSpawnHandler.markFBI(player);

		if(world.isRemote) return true;

		int[] pos = this.findCore(world, x, y, z);
		if(pos == null) return false;

		TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));
		if(!(te instanceof TileEntityRBMKRod)) return false;
		TileEntityRBMKRod rbmk = (TileEntityRBMKRod) te;

		if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() instanceof ItemRBMKLid) {
			if(!rbmk.hasLid()) return false;
		}

		if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() instanceof ItemRBMKRod && rbmk.slots[0] == null) {
			rbmk.slots[0] = com.hbm.util.NativeHeldItem.getMainHandNullable(player).copy();
			rbmk.slots[0].setCount(1);
			if(!player.capabilities.isCreativeMode) com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
			world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.0F, 1.0F);
			return false;
		}

		if(!player.isSneaking()) {
			FMLNetworkHandler.openGui(player, MainRegistry.instance, 0, world, pos[0], pos[1], pos[2]);
			return true;
		} else {
			return true;
		}
	}

@Override
	public void onNeighborBlockChange(World world, int x, int y, int z, Block block) {

		boolean on = world.isBlockIndirectlyGettingPowered(x, y, z);
		int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );

		boolean update = false;

		if(on && meta == 0) {
			world.setBlockMetadataWithNotify(x, y, z, 1, 2);
			world.playSoundEffect(x, y, z, "hbm:block.reactorStart", 1.0F, 1.0F);
			update = true;
		}

		if(!on && meta == 1) {
			world.setBlockMetadataWithNotify(x, y, z, 0, 2);
			world.playSoundEffect(x, y, z, "hbm:block.reactorStart", 1.0F, 0.85F);
			update = true;
		}

		if(update) {
			TileEntityCableSwitch te = (TileEntityCableSwitch) world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));
			te.updateState();
		}
	}

