public void killEvent(World world, int x, int y, int z) {

			world.playSoundEffect(x + 0.5D, y + 0.5D, z + 0.5D, "random.break", 1.0F, itemRand.nextFloat() * 0.4F + 0.8F);
			float f = this.explosionSize;
	        int i;
	        int j;
	        int k;
	        double d5;
	        double d6;
	        double d7;
	        double wat = 20.0D;


	        this.explosionSize *= 2.0F;
	        i = MathHelper.floor(x - wat - 1.0D);
	        j = MathHelper.floor(x + wat + 1.0D);
	        k = MathHelper.floor(y - wat - 1.0D);
	        int i2 = MathHelper.floor(y + wat + 1.0D);
	        int l = MathHelper.floor(z - wat - 1.0D);
	        int j2 = MathHelper.floor(z + wat + 1.0D);
	        List list = world.getEntitiesWithinAABBExcludingEntity(null, AxisAlignedBB.getBoundingBox(i, k, l, j, i2, j2));
	        Vec3d vec4 = new Vec3d(x, y + 1, z);

	        for (int i1 = 0; i1 < list.size(); ++i1)
	        {
	            Entity entity = (Entity)list.get(i1);
	            double d4 = entity.getDistance(x, y, z) / this.explosionSize;

	            if (d4 <= 1.0D)
	            {
	                d5 = entity.posX - x;
	                d6 = entity.posY + entity.getEyeHeight() - y;
	                d7 = entity.posZ - z;
	                double d9 = MathHelper.sqrt(d5 * d5 + d6 * d6 + d7 * d7);

	                if (d9 < wat)
	                {
	                    d5 /= d9;
	                    d6 /= d9;
	                    d7 /= d9;
	                    double d10 = world.getBlockDensity(vec4, entity.getEntityBoundingBox());
	                    double d11 = (1.0D - d4) * d10;
	                    //entity.attackEntityFrom(DamageSource.generic, (float)(100 - d9/wat*100/d10));

	                    if(!entity.world.isRemote && !entity.isDead)
	                    {
	                    	entity.setFire(50);
	                    	//entity.setDead();
	                    }

	                    //entity.attackEntityFrom(DamageSource.generic, (float)((int)((d11 * d11 + d11) / 2.0D * 8.0D * (double)this.explosionSize + 1.0D)));
	                    double d8 = EnchantmentProtection.func_92092_a(entity, d11);
	                    entity.motionX += d5 * d8;
	                    entity.motionY += d6 * d8;
	                    entity.motionZ += d7 * d8;

	                    if (entity instanceof EntityPlayer)
	                    {
	                        this.field_77288_k.put(entity, new Vec3d(d5 * d11, d6 * d11, d7 * d11));
	                    }
	                }
	            }
	        }

	        this.explosionSize = f;
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		if(!this.world.isRemote && this.ticksExisted % 5 == 0) {

			List<EntityItem> items = this.world.getEntitiesWithinAABB(EntityItem.class, AxisAlignedBB.getBoundingBox(
					posX - 2.5,
					posY - 1.5,
					posZ - 2.5,
					posX + 2.5,
					posY + 2,
					posZ + 2.5));

			boolean sound = false;

			outer: for(EntityItem item : items) {
				ItemStack stack = item.getEntityItem();

				//Match meta
				for(int i = 0; i < 9; i++) {
					ItemStack match = this.slots[i];

					if(match != null && match.getItem() == stack.getItem() && match.getItemDamage() == stack.getItemDamage()) {
						item.setDead();
						sound = true;
						continue outer;
					}
				}

				//Match wildcard
				for(int i = 9; i < 18; i++) {
					ItemStack match = this.slots[i];

					if(match != null && match.getItem() == stack.getItem()) {
						item.setDead();
						sound = true;
						continue outer;
					}
				}
			}

			if(sound)
				this.world.playSoundEffect(posX, posY, posZ, "mob.zombie.woodbreak", 0.5F, 0.5F + this.world.rand.nextFloat() * 0.2F);
		}

		if(this.world.isRemote && this.ticksExisted % 5 == 0) {
			this.world.spawnParticle("smoke", posX, posY + 0.75, posZ, 0.0, 0.01, 0.0);
		}
	}

public void teleportTo(Entity e, double x, double y, double z) {

		double targetX = e.posX;
		double targetY = e.posY;
		double targetZ = e.posZ;
		e.posX = x;
		e.posY = y;
		e.posZ = z;
		boolean flag = false;
		int i = MathHelper.floor(e.posX);
		int j = MathHelper.floor(e.posY);
		int k = MathHelper.floor(e.posZ);

		if(e.world.blockExists(i, j, k)) {
			boolean flag1 = false;

			while(!flag1 && j > 0) {
				Block block = e.world.getBlock(i, j - 1, k);

				if(block.getDefaultState().getMaterial().blocksMovement()) {
					flag1 = true;
				} else {
					--e.posY;
					--j;
				}
			}

			if(flag1) {
				e.setPosition(e.posX, e.posY, e.posZ);

				if(e.world.getCollidingBoundingBoxes(e, e.getEntityBoundingBox()).isEmpty() && !e.world.isAnyLiquid(e.getEntityBoundingBox())) {
					flag = true;
				}
			}
		}

		if(!flag) {
			e.setPosition(targetX, targetY, targetZ);
		} else {
			short short1 = 128;

			for(int l = 0; l < short1; ++l) {
				double d6 = (double) l / ((double) short1 - 1.0D);
				float f = (this.rand.nextFloat() - 0.5F) * 0.2F;
				float f1 = (this.rand.nextFloat() - 0.5F) * 0.2F;
				float f2 = (this.rand.nextFloat() - 0.5F) * 0.2F;
				double d7 = targetX + (e.posX - targetX) * d6 + (this.rand.nextDouble() - 0.5D) * (double) e.width * 2.0D;
				double d8 = targetY + (e.posY - targetY) * d6 + this.rand.nextDouble() * (double) e.height;
				double d9 = targetZ + (e.posZ - targetZ) * d6 + (this.rand.nextDouble() - 0.5D) * (double) e.width * 2.0D;
				e.world.spawnParticle("portal", d7, d8, d9, (double) f, (double) f1, (double) f2);
			}

			e.world.playSoundEffect(targetX, targetY, targetZ, "mob.endermen.portal", 1.0F, 1.0F);
			e.playSound("mob.endermen.portal", 1.0F, 1.0F);
		}
	}

