@Override
	public void onUpdate() {
		super.onUpdate();
		RocketState state = getState();

		if(!sizeSet) {
			setSize(2, (float)getRocket().getHeight() + 1);
			if(!this.world.isRemote && (state == RocketState.LANDED || state == RocketState.AWAITING || state == RocketState.NEEDSFUEL)) {
				TileEntity te = CompatExternal.getCoreFromPos(this.world, MathHelper.floor(posX), MathHelper.floor(posY + height - 1.0D), MathHelper.floor(posZ));

				if(te instanceof TileEntityOrbitalStation) {
					((TileEntityOrbitalStation)te).dockRocket(this);
				} else if(te instanceof TileEntityOrbitalStationLauncher) {
					((TileEntityOrbitalStationLauncher)te).dockRocket(this);
				}
			}
		}

		EntityPlayer rider = (EntityPlayer) this.riddenByEntity;

		if(!this.world.isRemote) {
			rotationYaw = -90.0F;

			if(navDrive != null && navDrive.getItem() instanceof ItemVOTVdrive) {
				ItemVOTVdrive.getTarget(navDrive, this.world);
				setDrive(navDrive);
			}

			if(thrower == null && rider != null) {
				thrower = rider;
			}

			// If it's a satellite launcher, launch immediately
			if(state == RocketState.AWAITING && ((rider != null && rider.isJumping) || !canRide())) {
				attemptLaunch();

				thrower = rider;
			}

			if(thrower != null && rider == null && !canExitCapsule() && forceExitTimer < 60) {
				thrower.mountEntity(this);
			}

			if(state == RocketState.LAUNCHING) {
				if(isReusable()) {
					rotationPitch = MathHelper.clamp((stateTimer - 60) * 0.3F, 0.0F, 45.0F);
					if(rocketVelocity < 4) rocketVelocity += MathHelper.clamp(stateTimer / 120D * 0.05D, (double) (0), 0.05);
				} else {
					double acceleration = stateTimer / 120D;
					rotationPitch = MathHelper.clamp((stateTimer - 80) * 0.3F, 0.0F, 45.0F);
					if(rocketVelocity < 4) rocketVelocity += MathHelper.clamp(acceleration * acceleration * 0.05D, (double) (0), 0.05);
				}

				// FUCK OPTIFINE
				if(FMLCommonHandler.instance().getSide() == Side.CLIENT && FMLClientHandler.instance().hasOptifine()) {
					rotationPitch = 0;
				}
			} else if(state == RocketState.LANDING) {
				double targetHeight = (double)this.world.getHeightValue((int)posX, (int)posZ);
				rotationPitch = 0;

				if(isReusable()) {
					rocketVelocity = MathHelper.clamp((targetHeight - posY) * 0.01, -1.0, -0.005);
				} else {
					rocketVelocity = MathHelper.clamp((targetHeight - posY) * 0.005, -0.5, -0.005);
				}

				if(destinationOverride == null && navDrive != null && navDrive.getItem() instanceof ItemVOTVdrive) {
					Destination destination = ItemVOTVdrive.getDestination(navDrive);

					// Check if we're about to land on top of another rocket and adjust accordingly
					AxisAlignedBB bb = this.getEntityBoundingBox().copy();
					bb.minY = targetHeight;
					if(!this.world.getEntitiesWithinAABBExcludingEntity(this, bb, entity -> entity instanceof EntityRideableRocket).isEmpty()) {
						int distance = this.world.rand.nextBoolean() ? -5 : 5;
						if(this.world.rand.nextBoolean()) {
							destination.x += distance;
							navDrive.getTagCompound().setInteger("x", destination.x);
						} else {
							destination.z += distance;
							navDrive.getTagCompound().setInteger("z", destination.z);
						}
					}

					posX = destination.x + 0.5D;
					posZ = destination.z + 0.5D;
				}
			} else if(state == RocketState.TIPPING) {
				float tipTime = (float)stateTimer * 0.1F;
				rotationPitch = tipTime * tipTime;

				if(rotationPitch > 90) {
					rotationPitch = 90;

					if(willExplode) {
						dropNDie(null);
						ExplosionLarge.explode(this.world, posX, posY, posZ, 5, true, false, true);
						ExplosionLarge.spawnShrapnelShower(this.world, posX, posY, posZ, motionX, motionY, motionZ, 15, 0.075);

						this.world.playSoundEffect(posX, posY, posZ, "hbm:entity.pipefail", 10_000, 0.8F + this.world.rand.nextFloat() * 0.4F);
					}
				}

				rocketVelocity = 0;
			} else if(state == RocketState.DOCKING) {
				// we have to wait for docking ports and their associated entities to load
				// waiting for loading using timers is bad, so maybe refactor this
				if(stateTimer > 20) {
					rocketVelocity = 0.1;
					rotationPitch = 0;

					if(targetPort == null) targetPort = OrbitalStation.getPort((int)posX, (int)posZ);

					// Just in case no ports have loaded in time, do nothing until they have
					if(targetPort != null) {
						posX = targetPort.getPos().getX() + 0.5D;
						posZ = targetPort.getPos().getZ() + 0.5D;

						targetPort.despawnRocket();
						targetPort.reservePort();

						if(posY + height > targetPort.getPos().getY() + 1.5D) {
							setState(isReusable() ? RocketState.NEEDSFUEL : RocketState.LANDED);
							destinationOverride = null;
							posY = targetPort.getPos().getY() + 1.5D - height;

							targetPort.dockRocket(this);
							targetPort = null;
						}
					} else {
						rocketVelocity = 0;
					}
				} else {
					rocketVelocity = 0;
					rotationPitch = 0;
				}
			} else if(state == RocketState.UNDOCKING) {
				rocketVelocity = -0.1;
				rotationPitch = 0;
			} else if(state == RocketState.TRANSFER) {
				rocketVelocity = 0;
				rotationPitch = 90;
				forceExitTimer = 0; // never allow exits in transfers under any circumstances!

				OrbitalStation station = OrbitalStation.getStationFromPosition((int)posX, (int)posZ);
				station.update(this.world);

				if(station.getUnscaledProgress(0) > 0.99 || station.state == StationState.ARRIVING) {
					Target from = CelestialBody.getTarget(this.world, (int)posX, (int)posZ);
					Target to = getTarget();

					beginLandingSequence(from, to);

					SolarSystemWorldSavedData data = SolarSystemWorldSavedData.get(this.world);
					data.removeStation(station);
				}

				PacketDispatcher.wrapper.sendTo(new EntityBufPacket(getEntityId(), this), (EntityPlayerMP) rider);
			} else {
				rocketVelocity = 0;
				rotationPitch = 0;
			}

			if(state == RocketState.LAUNCHING) {
				Vec3d motion = BobMathUtil.getDirectionFromAxisAngle(rotationPitch - 90.0F, 180.0F - rotationYaw, rocketVelocity);
				motionX = motion.x;
				motionY = motion.y;
				motionZ = motion.z;
			} else {
				motionX = 0;
				motionY = rocketVelocity;
				motionZ = 0;
			}

			if(state == RocketState.LANDING) {
				Material material = this.world.getBlock(MathHelper.floor(posX), MathHelper.floor(posY), MathHelper.floor(posZ)).getMaterial();

				if(material.isLiquid()) setState(RocketState.TIPPING);
				if(material == Material.LAVA) {
					setOnFireFromLava();
					willExplode = true;
				}
			}

			if((state == RocketState.LAUNCHING && posY > 900) || (state == RocketState.UNDOCKING && posY < 32)) {
				Target from = CelestialBody.getTarget(this.world, (int)posX, (int)posZ);
				Target to = getTarget();

				if(!canRide() || from.body == to.body) {
					beginLandingSequence(from, to);
				} else {
					beginCelestialTransfer(from, to);
				}
			}

			if(height > 8) {
				double offset = height - 4;
				if(capDummy == null || capDummy.isDead) {
					capDummy = new EntityRideableRocketDummy(this.world, this);
					capDummy.parent = this;
					capDummy.setPosition(posX, posY + offset, posZ);
					this.world.spawnEntityInWorld(capDummy);
				} else {
					capDummy.setPosition(posX, posY + offset, posZ);
				}
			} else if(capDummy != null) {
				capDummy.setDead();
				capDummy = null;
			}
		} else {
			// ON state transitions
			if(state != lastState) {
				if(state == RocketState.LAUNCHING) {
					AudioWrapper ignition = MainRegistry.proxy.getLoopedSound("hbm:entity.rocketIgnition", (float)posX, (float)posY, (float)posZ, 1.0F, 250.0F, 1.0F, 5);
					ignition.setDoesRepeat(false);
					ignition.startSound();
				}

				lastState = state;
				stateTimer = 0;
			} else {
				// We can't start audio loops at the same time as playing a sound, for some reason
				if(state == RocketState.LAUNCHING
				|| (state == RocketState.LANDING && motionY > -0.4)
				|| (state == RocketState.TRANSFER && OrbitalStation.clientStation.getUnscaledProgress(0) <= 0.15)) {
					if(audio == null || !audio.isPlaying()) {
						String rocketAudio = getRocket().stages.size() <= 1 ? "hbm:entity.rocketFlyLight" : "hbm:entity.rocketFlyHeavy";
						audio = MainRegistry.proxy.getLoopedSound(rocketAudio, (float)posX, (float)posY, (float)posZ, 1.0F, 250.0F, 1.0F, 5);
						audio.startSound();
					}

					audio.updatePosition((float)posX, (float)posY, (float)posZ);
					audio.keepAlive();
				} else {
					if(audio != null) {
						audio.stopSound();
						audio = null;
					}
				}
			}

			if(state == RocketState.TRANSFER) {
				OrbitalStation station = OrbitalStation.clientStation;
				station.update(this.world);

				if(station.getUnscaledProgress(0) > 0.2) {
					if(decoupleTimer == 0) {
						AudioWrapper decouple = MainRegistry.proxy.getLoopedSound("hbm:entity.rocketStage", (float)posX, (float)posY, (float)posZ, 0.5F, 250.0F, 0.9F + this.world.rand.nextFloat() * 0.2F, 40);
						decouple.setDoesRepeat(false);
						decouple.startSound();
					}

					if(decoupleTimer == 100 && getRocket().stages.size() > 1) {
						AudioWrapper decouple = MainRegistry.proxy.getLoopedSound("hbm:entity.rocketStage", (float)posX, (float)posY, (float)posZ, 0.5F, 250.0F, 1.2F + this.world.rand.nextFloat() * 0.2F, 40);
						decouple.setDoesRepeat(false);
						decouple.startSound();
					} else if(decoupleTimer > 100) {
						shroudTimer++;
					}

					decoupleTimer++;
				}
			} else {
				decoupleTimer = 0;
				shroudTimer = 0;
			}
		}

		setStateTimer(++stateTimer);
	}

@Override
	public void onUpdate() {

		if(motionY < 2.0D) {
			acceleration += 0.00025D;
			motionY += acceleration;
		}

		this.setLocationAndAngles(posX + this.motionX, posY + this.motionY, posZ + this.motionZ, 0, 0);

		if(!this.world.isRemote) {

			List<Entity> list = this.world.getEntitiesWithinAABBExcludingEntity(this, AxisAlignedBB.getBoundingBox(posX - 5, posY - 15, posZ - 5, posX + 5, posY, posZ + 5));

			for(Entity e : list) {
				e.setFire(15);
				e.attackEntityFrom(ModDamageSource.exhaust, 100.0F);

				if(e instanceof EntityPlayer) {
					if(!memed) {
						memed = true;
						this.world.playSoundEffect(posX, posY, posZ, "hbm:alarm.soyuzed", 100, 1.0F);
					}

					com.hbm.advancement.NtmAdvancements.award(((EntityPlayer)e), MainRegistry.achSoyuz);
				}
			}
		}

		if(this.world.isRemote) {
			spawnExhaust(posX, posY, posZ);
			spawnExhaust(posX + 2.75, posY, posZ);
			spawnExhaust(posX - 2.75, posY, posZ);
			spawnExhaust(posX, posY, posZ + 2.75);
			spawnExhaust(posX, posY, posZ - 2.75);
		}

		if(this.posY > 600) {
			deployPayload();
		}
	}

@Override
	protected void updateEntityActionState() {
		if(!this.world.isRemote && this.world.difficultySetting == EnumDifficulty.PEACEFUL) {
			this.setDead();
		}

		if(!isDying) {
			this.world.playSoundEffect(this.posX, this.posY, this.posZ, "hbm:misc.nullChopper", 10.0F, 0.5F);

			this.prevAttackCounter = this.attackCounter;
			double d0 = this.waypointX - this.posX;
			double d1 = this.waypointY - this.posY;
			double d2 = this.waypointZ - this.posZ;
			double d3 = d0 * d0 + d1 * d1 + d2 * d2;

			if(d3 < 1.0D || d3 > 3600.0D) {
				if(this.targetedEntity != null) {
					this.waypointX = targetedEntity.posX + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointZ = targetedEntity.posZ + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointY = this.world.getHeightValue((int) waypointX, (int) waypointZ) + 10 + rand.nextInt(15);
				} else {
					this.waypointX = this.posX + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointZ = this.posZ + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointY = this.world.getHeightValue((int) waypointX, (int) waypointZ) + 10 + rand.nextInt(15);
				}
			}

			if(this.courseChangeCooldown-- <= 0) {
				this.courseChangeCooldown += this.rand.nextInt(5) + 2;
				d3 = MathHelper.sqrt(d3);

				if(this.isCourseTraversable(this.waypointX, this.waypointY, this.waypointZ, d3)) {
					this.motionX += d0 / d3 * 0.1D;
					this.motionY += d1 / d3 * 0.1D;
					this.motionZ += d2 / d3 * 0.1D;
				} else {
					this.waypointX = this.posX + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointZ = this.posZ + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointY = this.world.getHeightValue((int) waypointX, (int) waypointZ) + 10 + rand.nextInt(15);
				}
			}

			if(this.targetedEntity != null && this.targetedEntity.isDead) {
				this.targetedEntity = null;
			}

			if(this.targetedEntity == null || this.attackCounter <= 0) {
				// this.targetedEntity =
				// this.worldObj.getClosestVulnerablePlayerToEntity(this,
				// 100.0D);
				this.targetedEntity = Library.getClosestEntityForChopper(this.world, this.posX, this.posY, this.posZ, 250);
			}

			double d4 = 64.0D;

			if(this.targetedEntity != null && this.targetedEntity.getDistanceSqToEntity(this) < d4 * d4) {
				double d8 = 2.0D;
				Vec3d vec3 = this.getLook(1.0F);
				double xStart = this.posX + vec3.x * d8;
				double yStart = this.posY - 0.5;
				double zStart = this.posZ + vec3.z * d8;
				double d5 = this.targetedEntity.posX - xStart;
				double d6 = this.targetedEntity.getEntityBoundingBox().minY + this.targetedEntity.height / 2.0F - yStart;
				double d7 = this.targetedEntity.posZ - zStart;

				++this.attackCounter;
				if(attackCounter >= 200) {
					attackCounter -= 200;
				}

				if(this.attackCounter % 2 == 0 && attackCounter >= 120) {
					this.world.playSoundAtEntity(this, "hbm:weapon.osiprShoot", 10.0F, 1.0F);
					// EntityLargeFireball entitylargefireball = new
					// EntityLargeFireball(this.worldObj, this, d5, d6, d7);
					EntityBullet entityarrow = new EntityBullet(this.world, this, 3.0F, 35, 45, false, "chopper");
					Vec3d vec2 = new Vec3d(d5 - 1 + rand.nextInt(3), d6 - 1 + rand.nextInt(3), d7 - 1 + rand.nextInt(3)).normalize();
					double motion = 3;
					entityarrow.motionX = vec2.x * motion;
					entityarrow.motionY = vec2.y * motion;
					entityarrow.motionZ = vec2.z * motion;
					// entitylargefireball.field_92057_e =
					// this.explosionStrength;
					entityarrow.setDamage(3 + rand.nextInt(5));
					// entitylargefireball.posX = this.posX + vec3.x * d8;
					// entitylargefireball.posY = this.posY +
					// (double)(this.height /
					// 2.0F) + 0.5D;
					// entitylargefireball.posZ = this.posZ + vec3.z * d8;
					entityarrow.posX = xStart;
					entityarrow.posY = yStart;
					entityarrow.posZ = zStart;
					// this.worldObj.spawnEntityInWorld(entitylargefireball);
					this.world.spawnEntityInWorld(entityarrow);
				}
				if(this.attackCounter == 80) {
					this.world.playSoundAtEntity(this, "hbm:entity.chopperCharge", 5.0F, 1.0F);
				}

				this.mineDropCounter++;
				if(mineDropCounter > 100 && rand.nextInt(15) == 0) {
					this.world.playSoundAtEntity(this, "hbm:entity.chopperDrop", 15.0F, 1.0F);
					EntityChopperMine mine = new EntityChopperMine(this.world, this.posX, this.posY - 0.5, this.posZ, 0, -0.3, 0, this);
					this.mineDropCounter = 0;
					this.world.spawnEntityInWorld(mine);

					if(rand.nextInt(3) == 0) {
						EntityChopperMine mine1 = new EntityChopperMine(this.world, this.posX, this.posY - 0.5, this.posZ, 1, -0.3, 0, this);
						EntityChopperMine mine2 = new EntityChopperMine(this.world, this.posX, this.posY - 0.5, this.posZ, 0, -0.3, 1, this);
						EntityChopperMine mine3 = new EntityChopperMine(this.world, this.posX, this.posY - 0.5, this.posZ, -1, -0.3, 0, this);
						EntityChopperMine mine4 = new EntityChopperMine(this.world, this.posX, this.posY - 0.5, this.posZ, 0, -0.3, -1, this);
						this.world.spawnEntityInWorld(mine1);
						this.world.spawnEntityInWorld(mine2);
						this.world.spawnEntityInWorld(mine3);
						this.world.spawnEntityInWorld(mine4);
					}
				}

			} else {

				if(this.attackCounter > 0) {
					this.attackCounter = 0;
				}
			}

			if(!this.world.isRemote) {
				byte b1 = this.dataWatcher.getWatchableObjectByte(16);
				byte b0 = (byte) (this.attackCounter > 10 ? 1 : 0);

				if(b1 != b0) {
					this.dataWatcher.updateObject(16, Byte.valueOf(b0));
				}
			}
		} else {
			motionY -= 0.08;
			if(Math.sqrt(Math.pow(this.motionX, 2) + Math.pow(this.motionZ, 2)) * 1.2 < 1.8) {
				this.motionX *= 1.2;
				this.motionZ *= 1.2;
			}

			if(rand.nextInt(20) == 0) {
				this.world.createExplosion(this, this.posX, this.posY, this.posZ, 5F, true);
			}

			if(!this.world.isRemote) {

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "exhaust");
				data.setString("mode", "meteor");
				data.setInteger("count", 10);
				data.setDouble("width", 1);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, posX, posY, posZ),  new TargetPoint(dimension, posX, posY, posZ, 100));
			}

			rotationYaw += 20;

			if(this.onGround) {
				this.world.createExplosion(this, this.posX, this.posY, this.posZ, 15F, true);
				this.dropItems();
				this.setDead();
			}
			if(this.ticksExisted % 2 == 0)
				this.world.playSoundEffect(this.posX, this.posY, this.posZ, "hbm:misc.nullCrashing", 10.0F, 0.5F);
		}

		if(this.targetedEntity == null) {
			float f3 = MathHelper.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ);
			if(this.rotationYaw - (float) (Math.atan2(this.motionX, this.motionZ) * 180.0D / Math.PI) >= 10)
				this.prevRotationYaw = this.rotationYaw -= 10;
			if(this.rotationYaw - (float) (Math.atan2(this.motionX, this.motionZ) * 180.0D / Math.PI) <= -10)
				this.prevRotationYaw = this.rotationYaw += 10;
			if(this.rotationYaw - (float) (Math.atan2(this.motionX, this.motionZ) * 180.0D / Math.PI) < 10 && this.rotationYaw - (float) (Math.atan2(this.motionX, this.motionZ) * 180.0D / Math.PI) > 10)
				this.prevRotationYaw = this.rotationYaw = (float) (Math.atan2(this.motionX, this.motionZ) * 180.0D / Math.PI);
			this.prevRotationPitch = this.rotationPitch = (float) (Math.atan2(this.motionY, f3) * 180.0D / Math.PI);
		} else {
			float f3 = MathHelper.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ);
			if(this.rotationYaw - (float) (Math.atan2(this.posX - targetedEntity.posX, this.posZ - targetedEntity.posZ) * 180.0D / Math.PI) >= 10)
				this.prevRotationYaw = this.rotationYaw -= 10;
			if(this.rotationYaw - (float) (Math.atan2(this.posX - targetedEntity.posX, this.posZ - targetedEntity.posZ) * 180.0D / Math.PI) <= -10)
				this.prevRotationYaw = this.rotationYaw += 10;
			if(this.rotationYaw - (float) (Math.atan2(this.posX - targetedEntity.posX, this.posZ - targetedEntity.posZ) * 180.0D / Math.PI) < 10 && this.rotationYaw - (float) (Math.atan2(this.posX - targetedEntity.posX, this.posZ - targetedEntity.posZ) * 180.0D / Math.PI) > 10)
				this.prevRotationYaw = this.rotationYaw = (float) (Math.atan2(this.posX - targetedEntity.posX, this.posZ - targetedEntity.posZ) * 180.0D / Math.PI);

			this.prevRotationPitch = this.rotationPitch = (float) (Math.atan2(this.motionY, f3) * 180.0D / Math.PI);

			this.getLook(1.0F);
		}

		if(rotationPitch <= 330 && rotationPitch >= 30) {
			if(rotationPitch < 180)
				rotationPitch = 30;
			if(rotationPitch >= 180)
				rotationPitch = 330;
		}
	}

@Override
	protected void updateEntityActionState() {
		if(!this.world.isRemote && this.world.difficultySetting == EnumDifficulty.PEACEFUL) {
			this.setDead();
		}

		if(!isDying) {
			this.world.playSoundEffect(this.posX, this.posY, this.posZ, "hbm:misc.nullChopper", 10.0F, 0.5F);

			this.prevAttackCounter = this.attackCounter;
			double d0 = this.waypointX - this.posX;
			double d1 = this.waypointY - this.posY;
			double d2 = this.waypointZ - this.posZ;
			double d3 = d0 * d0 + d1 * d1 + d2 * d2;

			if(d3 < 1.0D || d3 > 3600.0D) {
				if(this.targetedEntity != null) {
					this.waypointX = targetedEntity.posX + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointZ = targetedEntity.posZ + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointY = this.world.getHeightValue((int) waypointX, (int) waypointZ) + 10 + rand.nextInt(15);
				} else {
					this.waypointX = this.posX + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointZ = this.posZ + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointY = this.world.getHeightValue((int) waypointX, (int) waypointZ) + 10 + rand.nextInt(15);
				}
			}

			if(this.courseChangeCooldown-- <= 0) {
				this.courseChangeCooldown += this.rand.nextInt(5) + 2;
				d3 = MathHelper.sqrt(d3);

				if(this.isCourseTraversable(this.waypointX, this.waypointY, this.waypointZ, d3)) {
					this.motionX += d0 / d3 * 0.1D;
					this.motionY += d1 / d3 * 0.1D;
					this.motionZ += d2 / d3 * 0.1D;
				} else {
					this.waypointX = this.posX + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointZ = this.posZ + (this.rand.nextFloat() * 2.0F - 1.0F) * 16.0F;
					this.waypointY = this.world.getHeightValue((int) waypointX, (int) waypointZ) + 10 + rand.nextInt(15);
				}
			}

			if(this.targetedEntity != null && this.targetedEntity.isDead) {
				this.targetedEntity = null;
			}

			if(this.targetedEntity == null || this.attackCounter <= 0) {
				// this.targetedEntity =
				// this.worldObj.getClosestVulnerablePlayerToEntity(this,
				// 100.0D);
				this.targetedEntity = Library.getClosestEntityForChopper(this.world, this.posX, this.posY, this.posZ, 250);
			}

			double d4 = 64.0D;

			if(this.targetedEntity != null && this.targetedEntity.getDistanceSqToEntity(this) < d4 * d4) {
				double d8 = 2.0D;
				Vec3d vec3 = this.getLook(1.0F);
				double xStart = this.posX + vec3.x * d8;
				double yStart = this.posY - 0.5;
				double zStart = this.posZ + vec3.z * d8;
				double d5 = this.targetedEntity.posX - xStart;
				double d6 = this.targetedEntity.getEntityBoundingBox().minY + this.targetedEntity.height / 2.0F - yStart;
				double d7 = this.targetedEntity.posZ - zStart;

				++this.attackCounter;
				if(attackCounter >= 200) {
					attackCounter -= 200;
				}

				if(this.attackCounter % 2 == 0 && attackCounter >= 120) {
					this.world.playSoundAtEntity(this, "hbm:weapon.osiprShoot", 10.0F, 1.0F);
					// EntityLargeFireball entitylargefireball = new
					// EntityLargeFireball(this.worldObj, this, d5, d6, d7);
					EntityBullet entityarrow = new EntityBullet(this.world, this, 3.0F, 35, 45, false, "chopper");
					Vec3d vec2 = new Vec3d(d5 - 1 + rand.nextInt(3), d6 - 1 + rand.nextInt(3), d7 - 1 + rand.nextInt(3)).normalize();
					double motion = 3;
					entityarrow.motionX = vec2.x * motion;
					entityarrow.motionY = vec2.y * motion;
					entityarrow.motionZ = vec2.z * motion;
					// entitylargefireball.field_92057_e =
					// this.explosionStrength;
					entityarrow.setDamage(3 + rand.nextInt(5));
					// entitylargefireball.posX = this.posX + vec3.x * d8;
					// entitylargefireball.posY = this.posY +
					// (double)(this.height /
					// 2.0F) + 0.5D;
					// entitylargefireball.posZ = this.posZ + vec3.z * d8;
					entityarrow.posX = xStart;
					entityarrow.posY = yStart;
					entityarrow.posZ = zStart;
					// this.worldObj.spawnEntityInWorld(entitylargefireball);
					this.world.spawnEntityInWorld(entityarrow);
				}
				if(this.attackCounter == 80) {
					this.world.playSoundAtEntity(this, "hbm:entity.chopperCharge", 5.0F, 1.0F);
				}

				this.mineDropCounter++;
				if(mineDropCounter > 100 && rand.nextInt(15) == 0) {
					this.world.playSoundAtEntity(this, "hbm:entity.chopperDrop", 15.0F, 1.0F);
