@Override
	public void onDeath(DamageSource source) {
		super.onDeath(source);

		if(!this.world.isRemote && doesInfectedSpawnMaggots() && this.dataWatcher.getWatchableObjectByte(DW_SUBTYPE) == TYPE_INFECTED) {

			int j = 2 + this.rand.nextInt(3);

			for(int k = 0; k < j; ++k) {
				float f = ((float) (k % 2) - 0.5F) * 0.5F;
				float f1 = ((float) (k / 2) - 0.5F) * 0.5F;
				EntityParasiteMaggot maggot = new EntityParasiteMaggot(this.world);
				maggot.setLocationAndAngles(this.posX + (double) f, this.posY + 0.5D, this.posZ + (double) f1, this.rand.nextFloat() * 360.0F, 0.0F);
				maggot.motionX = f;
				maggot.motionZ = f1;
				maggot.velocityChanged = true;
				this.world.spawnEntityInWorld(maggot);
			}

			this.world.playSoundEffect(posX, posY, posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);

			NBTTagCompound vdat = new NBTTagCompound();
			vdat.setString("type", "giblets");
			vdat.setInteger("ent", this.getEntityId());
			PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, posX, posY + height * 0.5, posZ), new TargetPoint(dimension, posX, posY + height * 0.5, posZ, 150));

		}
	}

@Override
	public void onUpdate() {

		this.lastTickPosX = this.prevPosX = posX;
		this.lastTickPosY = this.prevPosY = posY;
		this.lastTickPosZ = this.prevPosZ = posZ;
		this.setPosition(posX + this.motionX, posY + this.motionY, posZ + this.motionZ);

		this.motionX *= 0.99;
		this.motionZ *= 0.99;
		this.motionY -= 0.05D;

		this.rotation();

		if(this.world.getBlock((int) this.posX, (int) this.posY, (int) this.posZ) != Blocks.AIR) {
			if(!this.world.isRemote) {
				if(type == 0) {
					ExplosionVNT vnt = new ExplosionVNT(this.world, this.posX + 0.5F, this.posY + 1.5F, this.posZ + 0.5F, 4F);
					vnt.setBlockAllocator(new BlockAllocatorStandard());
					vnt.setBlockProcessor(new BlockProcessorStandard());
					vnt.setEntityProcessor(new EntityProcessorCrossSmooth(1, 100));
					vnt.setPlayerProcessor(new PlayerProcessorStandard());
					vnt.setSFX(new ExplosionEffectWeapon(15, 3.5F, 1.25F));
					vnt.explode();
				}
				if(type == 1) {

					ExplosionVNT vnt = new ExplosionVNT(this.world, this.posX + 0.5F, this.posY + 1.5F, this.posZ + 0.5F, 4F);
					vnt.setBlockAllocator(new BlockAllocatorStandard());
					vnt.setBlockProcessor(new BlockProcessorStandard().withBlockEffect(new BlockMutatorFire()));
					vnt.setEntityProcessor(new EntityProcessorCrossSmooth(1, 100));
					vnt.setPlayerProcessor(new PlayerProcessorStandard());
					vnt.setSFX(new ExplosionEffectWeapon(15, 5F, 1.75F));
					vnt.explode();

				}
				if(type == 2) {
					this.world.playSoundEffect((double) (posX + 0.5F), (double) (posY + 0.5F), (double) (posZ + 0.5F), "random.fizz", 5.0F, 2.6F + (rand.nextFloat() - rand.nextFloat()) * 0.8F);
					EntityMist mist = new EntityMist(this.world);
					mist.setType(Fluids.CHLORINE);
					mist.setPosition(this.posX - motionX, this.posY - motionY, this.posZ - motionZ);
					mist.setArea(15, 7.5F);
					this.world.spawnEntityInWorld(mist);
				}
				if(type == 4) {
					this.world.spawnEntityInWorld(EntityNukeExplosionMK5.statFac(this.world, (int) (BombConfig.fatmanRadius * 1.5), posX, posY, posZ));

					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "muke");
					if(rand.nextInt(100) == 0)
						data.setBoolean("balefire", true);
					PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, posX, posY + 0.5, posZ), new TargetPoint(dimension, posX, posY, posZ, 250));
					com.hbm.sound.WorldSoundEffects.play(this.world, posX, posY, posZ, "hbm:weapon.mukeExplosion", 15.0F, 1.0F);
				}
				if(type == 9) {
					ExplosionVNT vnt = new ExplosionVNT(this.world, this.posX + 0.5F, this.posY + 1.5F, this.posZ + 0.5F, 4F);
					vnt.setEntityProcessor(new EntityProcessorCrossSmooth(1, 100));
					vnt.setPlayerProcessor(new PlayerProcessorStandard());
					vnt.setSFX(new ExplosionEffectWeapon(15, 3.5F, 1.25F));
					vnt.explode();
				}
				this.setDead();
			}
		}
	}

@Override
	protected void onImpact(RayTraceResult mop) {

		if(mop.typeOfHit == Type.BLOCK) {
			int x = mop.getBlockPos().getX();
			int y = mop.getBlockPos().getY();
			int z = mop.getBlockPos().getZ();

			boolean hRic = rand.nextInt(100) < config.HBRC;
			boolean doesRic = config.doesRicochet && hRic;

			if(!config.isSpectral && !doesRic) {
				this.setPosition(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z);
				this.onBlockImpact(x, y, z, mop.sideHit.getIndex());
			}

			if(doesRic) {

				Vec3d face = null;

				switch(mop.sideHit.getIndex()) {
				case 0: face = new Vec3d(0, -1, 0); break;
				case 1: face = new Vec3d(0, 1, 0); break;
				case 2: face = new Vec3d(0, 0, 1); break;
				case 3: face = new Vec3d(0, 0, -1); break;
				case 4: face = new Vec3d(-1, 0, 0); break;
				case 5: face = new Vec3d(1, 0, 0); break;
				}

				if(face != null) {

					Vec3d vel = new Vec3d(motionX, motionY, motionZ);
					vel.normalize();

					boolean lRic = rand.nextInt(100) < config.LBRC;
					double angle = Math.abs(BobMathUtil.getCrossAngle(vel, face) - 90);

					if(hRic || (angle <= config.ricochetAngle && lRic)) {
						switch(mop.sideHit.getIndex()) {
						case 0:
						case 1: motionY *= -1; break;
						case 2:
						case 3: motionZ *= -1; break;
						case 4:
						case 5: motionX *= -1; break;
						}

						if(config.plink == 1)
							this.world.playSoundAtEntity(this, "hbm:weapon.ricochet", 0.25F, 1.0F);
						if(config.plink == 2)
							this.world.playSoundAtEntity(this, "hbm:weapon.gBounce", 1.0F, 1.0F);

						this.setPosition(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z);
						onRicochet(x, y, z);

						//worldObj.setBlock((int) Math.floor(posX), (int) Math.floor(posY), (int) Math.floor(posZ), Blocks.dirt);

					} else {
						if(!this.world.isRemote) {
							this.setPosition(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z);
							onBlockImpact(x, y, z, mop.sideHit.getIndex());
						}
					}

					/*this.posX += (mop.hitVec.x - this.posX) * 0.6;
					this.posY += (mop.hitVec.y - this.posY) * 0.6;
					this.posZ += (mop.hitVec.z - this.posZ) * 0.6;*/

					this.motionX *= config.bounceMod;
					this.motionY *= config.bounceMod;
					this.motionZ *= config.bounceMod;
				}
			}

		}

		if(mop.entityHit != null) {

			DamageSource damagesource = this.config.getDamage(this, this.thrower);
			Entity victim = mop.entityHit;

			if(!config.doesPenetrate) {
				this.setPosition(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z);
				onEntityImpact(victim);
			} else {
				onEntityHurt(victim);
			}

			float damage = rand.nextFloat() * (config.dmgMax - config.dmgMin) + config.dmgMin;

			if(overrideDamage != 0)
				damage = overrideDamage;

			boolean headshot = false;

			if(victim instanceof EntityLivingBase && this.config.headshotMult > 1F) {
				EntityLivingBase living = (EntityLivingBase) victim;
				double head = living.height - living.getEyeHeight();

				if(!!living.isEntityAlive() && mop.hitVec != null && mop.hitVec.y > (living.posY + living.height - head * 2)) {
					damage *= this.config.headshotMult;
					headshot = true;
				}
			}

			if(victim != null && !victim.attackEntityFrom(damagesource, damage)) {

				try {
					Field lastDamage = ReflectionHelper.findField(EntityLivingBase.class, "lastDamage", "field_110153_bc");
					float dmg = (float) damage + lastDamage.getFloat(victim);
					if(!victim.attackEntityFrom(damagesource, dmg)) headshot = false;
				} catch (Exception x) { }

			}

			if(!this.world.isRemote && headshot) {
				if(victim instanceof EntityLivingBase) {
					EntityLivingBase living = (EntityLivingBase) victim;
					double head = living.height - living.getEyeHeight();
					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "vanillaburst");
					data.setInteger("count", 15);
					data.setDouble("motion", 0.1D);
					data.setString("mode", "blockdust");
					data.setInteger("block", Block.getIdFromBlock(Blocks.REDSTONE_BLOCK));
					PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, living.posX, living.posY + living.height - head, living.posZ), new TargetPoint(living.dimension, living.posX, living.posY, living.posZ, 50));
					this.world.playSoundEffect(victim.posX, victim.posY, victim.posZ, "mob.zombie.woodbreak", 1.0F, 0.95F + rand.nextFloat() * 0.2F);
				}
			}
		}
	}

private void onBlockImpact(int bX, int bY, int bZ, int sideHit) {
		Block block = this.world.getBlock(bX, bY, bZ);

		if(config.bntImpact != null)
			config.bntImpact.behaveBlockHit(this, bX, bY, bZ, sideHit);

		if(!this.world.isRemote) {
			if(!config.liveAfterImpact && !config.isSpectral && bY > -1 && !this.inGround) this.setDead();
			if(!config.doesPenetrate && bY == -1) this.setDead();
		}

		if(config.incendiary > 0 && !this.world.isRemote) {
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX, (int)posY, (int)posZ) == Blocks.AIR) this.world.setBlock((int)posX, (int)posY, (int)posZ, Blocks.FIRE);
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX + 1, (int)posY, (int)posZ) == Blocks.AIR) this.world.setBlock((int)posX + 1, (int)posY, (int)posZ, Blocks.FIRE);
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX - 1, (int)posY, (int)posZ) == Blocks.AIR) this.world.setBlock((int)posX - 1, (int)posY, (int)posZ, Blocks.FIRE);
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX, (int)posY + 1, (int)posZ) == Blocks.AIR) this.world.setBlock((int)posX, (int)posY + 1, (int)posZ, Blocks.FIRE);
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX, (int)posY - 1, (int)posZ) == Blocks.AIR) this.world.setBlock((int)posX, (int)posY - 1, (int)posZ, Blocks.FIRE);
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX, (int)posY, (int)posZ + 1) == Blocks.AIR) this.world.setBlock((int)posX, (int)posY, (int)posZ + 1, Blocks.FIRE);
			if(this.world.rand.nextInt(3) == 0 && this.world.getBlock((int)posX, (int)posY, (int)posZ - 1) == Blocks.AIR) this.world.setBlock((int)posX, (int)posY, (int)posZ - 1, Blocks.FIRE);
		}

		if(config.emp > 0)
			ExplosionNukeGeneric.empBlast(this.world, (int)(this.posX + 0.5D), (int)(this.posY + 0.5D), (int)(this.posZ + 0.5D), config.emp);

		if(config.emp > 3) {
			if (!this.world.isRemote) {

				EntityEMPBlast cloud = new EntityEMPBlast(this.world, config.emp);
				cloud.posX = this.posX;
				cloud.posY = this.posY + 0.5F;
				cloud.posZ = this.posZ;

				this.world.spawnEntityInWorld(cloud);
			}
		}

		if(config.jolt > 0 && !this.world.isRemote)
			ExplosionLarge.jolt(this.world, posX, posY, posZ, config.jolt, 150, 0.25);

		if(config.explosive > 0 && !this.world.isRemote) {
			//worldObj.newExplosion(this.thrower, posX, posY, posZ, config.explosive, config.incendiary > 0, config.blockDamage);
			ExplosionVNT vnt = new ExplosionVNT(this.world, posX, posY, posZ, config.explosive, this.thrower);
			vnt.setBlockAllocator(new BlockAllocatorStandard());
			if(config.blockDamage)	vnt.setBlockProcessor(new BlockProcessorStandard().withBlockEffect(config.incendiary > 0 ? new BlockMutatorFire() : null));
			else					vnt.setBlockProcessor(new BlockProcessorNoDamage().withBlockEffect(config.incendiary > 0 ? new BlockMutatorFire() : null));
			vnt.setEntityProcessor(new EntityProcessorStandard().allowSelfDamage());
			vnt.setPlayerProcessor(new PlayerProcessorStandard());
			vnt.setSFX(new ExplosionEffectStandard());
			vnt.explode();
		}

		if(config.shrapnel > 0 && !this.world.isRemote)
			ExplosionLarge.spawnShrapnels(this.world, posX, posY, posZ, config.shrapnel);

		if(config.rainbow > 0 && !this.world.isRemote) {
			EntityNukeExplosionMK3 ex = EntityNukeExplosionMK3.statFacFleija(this.world, posX, posY, posZ, config.rainbow);
			if(!ex.isDead) {
				this.world.playSoundEffect(this.posX, this.posY, this.posZ, "random.explode", 100.0f, this.world.rand.nextFloat() * 0.1F + 0.9F);
				this.world.spawnEntityInWorld(ex);

				EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(this.world, config.rainbow);
				cloud.posX = this.posX;
				cloud.posY = this.posY;
				cloud.posZ = this.posZ;
				this.world.spawnEntityInWorld(cloud);
			}
		}

		if(config.nuke > 0 && !this.world.isRemote) {
			this.world.spawnEntityInWorld(EntityNukeExplosionMK5.statFac(this.world, config.nuke, posX, posY, posZ));
			NBTTagCompound data = new NBTTagCompound();
			data.setString("type", "muke");
			if(MainRegistry.polaroidID == 11 || rand.nextInt(100) == 0) data.setBoolean("balefire", true);
			PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, posX, posY + 0.5, posZ), new TargetPoint(dimension, posX, posY, posZ, 250));
			com.hbm.sound.WorldSoundEffects.play(this.world, posX, posY, posZ, "hbm:weapon.mukeExplosion", 15.0F, 1.0F);
		}

		if(config.destroysBlocks && !this.world.isRemote) {
			if(block.getBlockHardness(this.world, bX, bY, bZ) <= 120)
				this.world.func_147480_a(bX, bY, bZ, false);
		} else if(config.doesBreakGlass && !this.world.isRemote) {
			if(block == Blocks.GLASS || block == Blocks.GLASS_PANE || block == Blocks.STAINED_GLASS || block == Blocks.STAINED_GLASS_PANE)
				this.world.func_147480_a(bX, bY, bZ, false);

			if(block instanceof BlockDetonatable) {
				((BlockDetonatable) block).onShot(this.world, bX, bY, bZ);
			}
		}
	}

public boolean teleportTo(Entity e, double x, double y, double z) {

		double targetX = e.posX;
		double targetY = e.posY;
		double targetZ = e.posZ;
		e.posX = x;
		e.posY = y;
		e.posZ = z;
		boolean flag = false;
		int i = MathHelper.floor(e.posX);
		int j = MathHelper.floor(e.posY);
		int k = MathHelper.floor(e.posZ);

		if(e.world.blockExists(i, j, k)) {
			boolean flag1 = false;

			while(!flag1 && j > 0) {
				Block block = e.world.getBlock(i, j - 1, k);

				if(block.getDefaultState().getMaterial().blocksMovement()) {
					flag1 = true;
				} else {
					--e.posY;
					--j;
				}
			}

			if(flag1) {
				e.setPosition(e.posX, e.posY, e.posZ);

				if(e.world.getCollidingBoundingBoxes(e, e.getEntityBoundingBox()).isEmpty() && !e.world.isAnyLiquid(e.getEntityBoundingBox())) {
					flag = true;
				}
			}
		}

		if(!flag) {
			e.setPosition(targetX, targetY, targetZ);
			return false;
		} else {
			short short1 = 128;

			for(int l = 0; l < short1; ++l) {
				double d6 = (double) l / ((double) short1 - 1.0D);
				float f = (this.rand.nextFloat() - 0.5F) * 0.2F;
				float f1 = (this.rand.nextFloat() - 0.5F) * 0.2F;
				float f2 = (this.rand.nextFloat() - 0.5F) * 0.2F;
				double d7 = targetX + (e.posX - targetX) * d6 + (this.rand.nextDouble() - 0.5D) * (double) e.width * 2.0D;
				double d8 = targetY + (e.posY - targetY) * d6 + this.rand.nextDouble() * (double) e.height;
				double d9 = targetZ + (e.posZ - targetZ) * d6 + (this.rand.nextDouble() - 0.5D) * (double) e.width * 2.0D;
				e.world.spawnParticle("portal", d7, d8, d9, (double) f, (double) f1, (double) f2);
			}

			e.world.playSoundEffect(targetX, targetY, targetZ, "mob.endermen.portal", 1.0F, 1.0F);
			e.playSound("mob.endermen.portal", 1.0F, 1.0F);
			return true;
		}
	}

@Override
	protected void onImpact(RayTraceResult mop) {

		if(this.world != null && mop != null && mop.typeOfHit == Type.ENTITY && mop.entityHit.isEntityAlive()) {
			Entity e = mop.entityHit;
			e.attackEntityFrom(ModDamageSource.rubble, 1000);
			if(!e.isEntityAlive() && e instanceof EntityLivingBase) {
				NBTTagCompound vdat = new NBTTagCompound();
				vdat.setString("type", "giblets");
				vdat.setInteger("ent", e.getEntityId());
				vdat.setInteger("cDiv", 5);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, e.posX, e.posY + e.height * 0.5, e.posZ), new TargetPoint(e.dimension, e.posX, e.posY + e.height * 0.5, e.posZ, 150));

				this.world.playSoundEffect(e.posX, e.posY, e.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
			}
		}

		if(this.ticksExisted > 1 && this.world != null && mop != null && mop.typeOfHit == Type.BLOCK) {

			int orientation = this.dataWatcher.getWatchableObjectInt(10);

			if(orientation < 6) {

				if(new Vec3d(motionX, motionY, motionZ).length() < 0.75) {
					this.dataWatcher.updateObject(10, orientation + 6);
					orientation += 6;
				} else {
					net.minecraft.util.EnumFacing side = mop.sideHit;
					this.motionX *= 1 - (Math.abs(side.getFrontOffsetX()) * 2);
					this.motionY *= 1 - (Math.abs(side.getFrontOffsetY()) * 2);
					this.motionZ *= 1 - (Math.abs(side.getFrontOffsetZ()) * 2);
					this.world.createExplosion(this, posX, posY, posZ, 3F, false);

					if(this.world.getBlockState(mop.getBlockPos()).getBlock().getExplosionResistance(this) < 50) {
						this.world.func_147480_a(mop.getBlockPos().getX(), mop.getBlockPos().getY(), mop.getBlockPos().getZ(), false);
					}
				}
			}

			if(orientation >= 6) {
				this.motionX = 0;
				this.motionY = 0;
				this.motionZ = 0;
				this.inGround = true;
			}
		}
	}

private void explode() {
    	if(!this.world.isRemote) {
    		EntityNukeExplosionMK3 ex = EntityNukeExplosionMK3.statFacFleija(this.world, posX, posY, posZ, 10);
    		if(!ex.isDead) {
				this.world.playSoundEffect(this.posX, this.posY, this.posZ, "random.explode", 100.0f, this.world.rand.nextFloat() * 0.1F + 0.9F);
				this.world.spawnEntityInWorld(ex);


	    		EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(this.world, 10);
	    		cloud.posX = this.posX;
	    		cloud.posY = this.posY;
	    		cloud.posZ = this.posZ;
	    		this.world.spawnEntityInWorld(cloud);
    		}
    	}
    }

