@Override
	protected void onImpact(RayTraceResult mop) {
		int blockX = mop.getBlockPos().getX();
		int blockY = mop.getBlockPos().getY();
		int blockZ = mop.getBlockPos().getZ();
		if(mop.entityHit != null) {
			byte b0 = 15;

			mop.entityHit.attackEntityFrom(ModDamageSource.shrapnel, b0);
		}

		if(this.ticksExisted > 5) {

			if(!this.world.isRemote)
				this.setDead();

			int b = this.dataWatcher.getWatchableObjectByte(16);
			if(b == 2 || b == 4) {

				if(!this.world.isRemote) {
					if(motionY < -0.2D) {

						if(this.world.getBlock(blockX, blockY + 1, blockZ).isReplaceable(this.world, blockX, blockY + 1, blockZ))
							this.world.setBlock(blockX, blockY + 1, blockZ, b == 2 ? ModBlocks.volcanic_lava_block : ModBlocks.rad_lava_block);

						for(int x = blockX - 1; x <= blockX + 1; x++) {
							for(int y = blockY; y <= blockY + 2; y++) {
								for(int z = blockZ - 1; z <= blockZ + 1; z++) {
									if(this.world.getBlock(x, y, z) == Blocks.AIR)
										this.world.setBlock(x, y, z, ModBlocks.gas_monoxide);
								}
							}
						}
					}

					if(motionY > 0) {
						ExplosionNT explosion = new ExplosionNT(this.world, null, blockX + 0.5, blockY + 0.5, blockZ + 0.5, 7);
						explosion.addAttrib(ExAttrib.NODROP);
						explosion.addAttrib(b == 2 ? ExAttrib.LAVA_V : ExAttrib.LAVA_R);
						explosion.addAttrib(ExAttrib.NOSOUND);
						explosion.addAttrib(ExAttrib.ALLMOD);
						explosion.addAttrib(ExAttrib.NOHURT);
						explosion.explode();
					}
				}

			} else if(this.dataWatcher.getWatchableObjectByte(16) == 3) {

				if(this.world.getBlock(blockX, blockY + 1, blockZ).isReplaceable(this.world, blockX, blockY + 1, blockZ)) {
					this.world.setBlock(blockX, blockY + 1, blockZ, ModBlocks.mud_block);
				}

			} else {

				for(int i = 0; i < 5; i++) this.world.spawnParticle("lava", posX, posY, posZ, 0.0, 0.0, 0.0);
			}

			this.world.playSoundEffect(posX, posY, posZ, "random.fizz", 1.0F, 1.0F);
		}
	}

@Override
	public void onUpdate() {

		this.lastTickPosX = this.prevPosX = posX;
		this.lastTickPosY = this.prevPosY = posY;
		this.lastTickPosZ = this.prevPosZ = posZ;
		this.setPosition(posX + this.motionX, posY + this.motionY, posZ + this.motionZ);

		if(this.ticksExisted % 100 == 0) {
			this.world.playSoundEffect(posX, posY, posZ, "hbm:alarm.chime", 10000, 1.0F);
		}

		motionY = -0.5;

		if(this.world.getBlock((int) this.posX, (int) this.posY, (int) this.posZ) != Blocks.AIR || this.posY < 10) {
			if(!this.world.isRemote) {
				EntityTomBlast tom = new EntityTomBlast(this.world);
				tom.posX = posX;
				tom.posY = posY;
				tom.posZ = posZ;
				tom.destructionRange = 600;
				this.world.spawnEntityInWorld(tom);

				EntityCloudTom cloud = new EntityCloudTom(this.world, 500);
				cloud.setLocationAndAngles(posX, posY, posZ, 0, 0);
				this.world.spawnEntityInWorld(cloud);
			}
			this.setDead();
		}
	}

public void doExplosionB(boolean p_77279_1_) {

		if(!has(ExAttrib.NOSOUND))
			this.worldObj.playSoundEffect(this.explosionX, this.explosionY, this.explosionZ, "random.explode", 4.0F, (1.0F + (this.worldObj.rand.nextFloat() - this.worldObj.rand.nextFloat()) * 0.2F) * 0.7F);

		if(!has(ExAttrib.NOPARTICLE)) {
			if(this.explosionSize >= 2.0F && this.isSmoking) {
				this.worldObj.spawnParticle("hugeexplosion", this.explosionX, this.explosionY, this.explosionZ, 1.0D, 0.0D, 0.0D);
			} else {
				this.worldObj.spawnParticle("largeexplode", this.explosionX, this.explosionY, this.explosionZ, 1.0D, 0.0D, 0.0D);
			}
		}

		Iterator iterator;
		BlockPos chunkposition;
		int i;
		int j;
		int k;
		Block block;

		if(this.isSmoking) {
			iterator = this.getAffectedBlockPositions().iterator();

			while(iterator.hasNext()) {
				chunkposition = (BlockPos) iterator.next();
				i = chunkposition.getX();
				j = chunkposition.getY();
				k = chunkposition.getZ();
				block = com.hbm.world.WorldBlockState.read(this.worldObj, i, j, k).getBlock();

				if(!has(ExAttrib.NOPARTICLE)) {
					double d0 = (double) ((float) i + this.worldObj.rand.nextFloat());
					double d1 = (double) ((float) j + this.worldObj.rand.nextFloat());
					double d2 = (double) ((float) k + this.worldObj.rand.nextFloat());
					double d3 = d0 - this.explosionX;
					double d4 = d1 - this.explosionY;
					double d5 = d2 - this.explosionZ;
					double d6 = (double) MathHelper.sqrt(d3 * d3 + d4 * d4 + d5 * d5);
					d3 /= d6;
					d4 /= d6;
					d5 /= d6;
					double d7 = 0.5D / (d6 / (double) this.explosionSize + 0.1D);
					d7 *= (double) (this.worldObj.rand.nextFloat() * this.worldObj.rand.nextFloat() + 0.3F);
					d3 *= d7;
					d4 *= d7;
					d5 *= d7;
					this.worldObj.spawnParticle("explode", (d0 + this.explosionX * 1.0D) / 2.0D, (d1 + this.explosionY * 1.0D) / 2.0D, (d2 + this.explosionZ * 1.0D) / 2.0D, d3, d4, d5);
					this.worldObj.spawnParticle("smoke", d0, d1, d2, d3, d4, d5);
				}

				if(block.getDefaultState().getMaterial() != Material.AIR) {
					
					boolean doesErrode = false;
					Block errodesInto = Blocks.AIR;
					
					if(this.has(ExAttrib.ERRODE) && this.explosionRNG.nextFloat() < 0.6F) { //errosion has a 60% chance to occour
						
						if(errosion.containsKey(block)) {
							doesErrode = true;
							errodesInto = errosion.get(block);
						}
					}
					
					if(block.canDropFromExplosion(this) && !has(ExAttrib.NODROP) && !doesErrode) {
						float chance = 1.0F;

						if(!has(ExAttrib.ALLDROP))
							chance = 1.0F / this.explosionSize;

						block.dropBlockAsItemWithChance(this.worldObj, i, j, k, com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(this.worldObj, i, j, k) ), chance, 0);
					}

					block.onBlockExploded(this.worldObj, i, j, k, this);
					
					if(block.isNormalCube()) {
						
						if(doesErrode) {
							this.worldObj.setBlock(i, j, k, errodesInto);
						}
						
