public static BulletConfiguration getRocketUFOConfig() {

		BulletConfiguration bullet = GunRocketFactory.getRocketConfig();

		bullet.vPFX = "reddust";
		bullet.destroysBlocks = false;
		bullet.explosive = 0F;

		bullet.bntUpdate = new IBulletUpdateBehaviorNT() {

			double angle = 90;
			double range = 100;

			@Override
			public void behaveUpdate(EntityBulletBaseNT bullet) {

				if(bullet.world.isRemote)
					return;

				if(bullet.world.getEntityByID(bullet.getEntityData().getInteger("homingTarget")) == null) {
					chooseTarget(bullet);
				}

				Entity target = bullet.world.getEntityByID(bullet.getEntityData().getInteger("homingTarget"));

				if(target != null) {

					if(bullet.getDistanceSqToEntity(target) < 5) {
						bullet.getConfig().bntImpact.behaveBlockHit(bullet, -1, -1, -1, -1);
						bullet.setDead();
						return;
					}

					Vec3d delta = new Vec3d(target.posX - bullet.posX, target.posY + target.height / 2 - bullet.posY, target.posZ - bullet.posZ);
					delta = delta.normalize();

					double vel = new Vec3d(bullet.motionX, bullet.motionY, bullet.motionZ).length();

					bullet.motionX = delta.x * vel;
					bullet.motionY = delta.y * vel;
					bullet.motionZ = delta.z * vel;
				}
			}

			private void chooseTarget(EntityBulletBaseNT bullet) {

				List<EntityLivingBase> entities = bullet.world.getEntitiesWithinAABB(EntityLivingBase.class, bullet.getEntityBoundingBox().expand(range, range, range));

				Vec3d mot = new Vec3d(bullet.motionX, bullet.motionY, bullet.motionZ);

				EntityLivingBase target = null;
				double targetAngle = angle;

				for(EntityLivingBase e : entities) {

					if(!e.isEntityAlive() || e == bullet.getThrower())
						continue;

					Vec3d delta = new Vec3d(e.posX - bullet.posX, e.posY + e.height / 2 - bullet.posY, e.posZ - bullet.posZ);

					if(bullet.world.rayTraceBlocks(new Vec3d(bullet.posX, bullet.posY, bullet.posZ), new Vec3d(e.posX, e.posY + e.height / 2, e.posZ), false, true, false) != null)
						continue;

					double dist = e.getDistanceSqToEntity(bullet);

					if(dist < range * range) {

						double deltaAngle = BobMathUtil.getCrossAngle(mot, delta);

						if(deltaAngle < targetAngle) {
							target = e;
							targetAngle = deltaAngle;
						}
					}
				}

				if(target != null) {
					bullet.getEntityData().setInteger("homingTarget", target.getEntityId());
				}
			}
		};

		bullet.bntImpact = (bulletnt, x, y, z, sideHit) -> {

			com.hbm.sound.WorldSoundEffects.play(bulletnt.world, bulletnt.posX, bulletnt.posY, bulletnt.posZ, "hbm:entity.ufoBlast", 5.0F, 0.9F + bulletnt.world.rand.nextFloat() * 0.2F);
			bulletnt.world.playSoundEffect(bulletnt.posX, bulletnt.posY, bulletnt.posZ, "fireworks.blast", 5.0F, 0.5F);
			ExplosionNukeGeneric.dealDamage(bulletnt.world, bulletnt.posX, bulletnt.posY, bulletnt.posZ, 10, 50);

			for(int i = 0; i < 3; i++) {
				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "plasmablast");
				data.setFloat("r", 0.0F);
				data.setFloat("g", 0.75F);
				data.setFloat("b", 1.0F);
				data.setFloat("pitch", -30F + 30F * i);
				data.setFloat("yaw", bulletnt.world.rand.nextFloat() * 180F);
				data.setFloat("scale", 5F);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, bulletnt.posX, bulletnt.posY, bulletnt.posZ),
						new TargetPoint(bulletnt.world.provider.getDimension(), bulletnt.posX, bulletnt.posY, bulletnt.posZ, 100));
			}
		};

		return bullet;
	}

@Override
	public ItemStack onItemRightClick(ItemStack stack, World world, EntityPlayer player) {
		boolean isProcessed = getProcessed(stack);
		boolean onDestination = world.provider.getDimension() == getDestination(stack).body.getDimensionId();

		// If we're on the body (or in creative), immediately process
		if(!isProcessed && (player.capabilities.isCreativeMode || onDestination)) {
			isProcessed = true;
			setProcessed(stack, true);
		}

		ItemStack newStack = stack;

		if(isProcessed && player.ridingEntity != null && player.ridingEntity instanceof EntityRideableRocket) {
			EntityRideableRocket rocket = (EntityRideableRocket) player.ridingEntity;

			if(rocket.getRocket().stages.size() > 0 || world.provider.getDimension() == SpaceConfig.orbitDimension || rocket.isReusable()) {
				if(rocket.getState() == RocketState.LANDED || rocket.getState() == RocketState.AWAITING) {
					// Replace our held stack with the rocket drive and place our held drive into the rocket
					if(rocket.navDrive != null) {
						newStack = rocket.navDrive;
					} else {
						newStack.stackSize = 0;
					}

					rocket.navDrive = stack.copy();
					rocket.navDrive.setCount(1);

					if(!world.isRemote) {
						rocket.setState(RocketState.AWAITING);
					}

					world.playSoundEffect(player.posX, player.posY, player.posZ, "hbm:item.upgradePlug", 1.0F, 1.0F);
				}
			}
		}

		return newStack;
	}

@Override
	public void orchestra(ItemStack stack, LambdaContext ctx) {
		EntityLivingBase entity = ctx.entity;
		if(entity.world.isRemote) return;
		GunAnimation type = ItemGunBaseNT.getLastAnim(stack, ctx.configIndex);
		int timer = ItemGunBaseNT.getAnimTimer(stack, ctx.configIndex);

		boolean swings = type == GunAnimation.CYCLE && (timer == 5 || timer == 15);
		boolean sweep = type == GunAnimation.ALT_CYCLE && timer == 5;

		if((swings || sweep) && ctx.getPlayer() != null) {
			RayTraceResult mop = EntityDamageUtil.getMouseOver(ctx.getPlayer(), 3.0D, 0.5D);

			if(mop != null) {
				if(mop.typeOfHit == RayTraceResult.Type.ENTITY && mop.entityHit.isEntityAlive()) {
					float damage = swings ? 15F : 35F;
					float knockback = swings ? 0F : 1.5F;
					float dt = swings ? 5F : 15F;
					float pierce = swings ? 0.1F : 0.25F;

					if(mop.entityHit instanceof EntityLivingBase) {
						EntityLivingBase living = (EntityLivingBase) mop.entityHit;
						if(living.getMaxHealth() >= 100) damage *= 2.5;
						EntityDamageUtil.attackEntityFromNT((EntityLivingBase) mop.entityHit, DamageSource.causePlayerDamage(ctx.getPlayer()), damage, true, false, knockback, dt, pierce);
						if(!living.isEntityAlive()) ConfettiUtil.gib(living);
					} else {
						mop.entityHit.attackEntityFrom(DamageSource.causePlayerDamage(ctx.getPlayer()), damage);
					}

					entity.world.playSoundAtEntity(mop.entityHit, "hbm:weapon.fire.stab", 1F, 0.9F + entity.getRNG().nextFloat() * 0.2F);
				}
				if(mop.typeOfHit == RayTraceResult.Type.BLOCK) {
					Block b = entity.world.getBlockState(mop.getBlockPos()).getBlock();
					entity.world.playSoundEffect(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z, b.stepSound.getStepResourcePath(), 2F, 0.9F + entity.getRNG().nextFloat() * 0.2F);
				}
			}
		}
	}

@Override
	public void orchestra(ItemStack stack, LambdaContext ctx) {
		EntityLivingBase entity = ctx.entity;
		if(entity.world.isRemote) return;
		GunAnimation type = ItemGunBaseNT.getLastAnim(stack, ctx.configIndex);
		int timer = ItemGunBaseNT.getAnimTimer(stack, ctx.configIndex);

		// refire check so you can just continuously beat the shit out of someone
		if(type == GunAnimation.CYCLE && timer == 14 && ItemGunBaseNT.getPrimary(stack, 0)) {
			XFactoryPA.doSwing(stack, ctx, GunAnimation.CYCLE, 14);
		}

		boolean swings = type == GunAnimation.CYCLE && (timer == 3 || timer == 9);
		boolean slap = type == GunAnimation.ALT_CYCLE && timer == 8;

		if((swings || slap) && ctx.getPlayer() != null) {
			RayTraceResult mop = EntityDamageUtil.getMouseOver(ctx.getPlayer(), 3.0D, 0.5D);

			if(mop != null) {
				if(mop.typeOfHit == RayTraceResult.Type.ENTITY) {
					float damage = swings ? 15F : 35F;
					float knockback = swings ? 0F : 1.5F;
					float dt = swings ? 5F : 15F;
					float pierce = swings ? 0.1F : 0.25F;

					if(mop.entityHit instanceof EntityLivingBase) {
						EntityLivingBase living = (EntityLivingBase) mop.entityHit;
						if(living.getMaxHealth() >= 100) damage *= 2.5;
						EntityDamageUtil.attackEntityFromNT((EntityLivingBase) mop.entityHit, DamageSource.causePlayerDamage(ctx.getPlayer()), damage, true, false, knockback, dt, pierce);
						if(living.getRNG().nextInt(slap ? 3 : 10) == 0 && !living.isEntityAlive()) ConfettiUtil.gib(living);
					} else {
						mop.entityHit.attackEntityFrom(DamageSource.causePlayerDamage(ctx.getPlayer()), damage);
					}

					entity.world.playSoundAtEntity(mop.entityHit, "hbm:weapon.fire.smack", 1F, 0.9F + entity.getRNG().nextFloat() * 0.2F);
				}
				if(mop.typeOfHit == RayTraceResult.Type.BLOCK) {
					Block b = entity.world.getBlockState(mop.getBlockPos()).getBlock();
					entity.world.playSoundEffect(mop.hitVec.x, mop.hitVec.y, mop.hitVec.z, b.stepSound.getStepResourcePath(), 2F, 0.9F + entity.getRNG().nextFloat() * 0.2F);
				}
			}
		}
	}

@Override
	protected void onFoodEaten(ItemStack stack, World world, EntityPlayer player)
	{
		if(this == ModItems.med_ipecac || this == ModItems.med_ptsd) {
			player.addPotionEffect(new PotionEffect(Potion.hunger.id, 50, 49));
			HbmPlayerProps props = HbmPlayerProps.getData(player);
			if (props.nitanCount > 0){
				player.removePotionEffect(HbmPotion.nitan.id);
				props.nitanCount = 0;
			}
			NBTTagCompound nbt = new NBTTagCompound();
			nbt.setString("type", "vomit");
			nbt.setInteger("entity", player.getEntityId());
			PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(player.dimension, player.posX, player.posY, player.posZ, 25));

			world.playSoundEffect(player.posX, player.posY, player.posZ, "hbm:entity.vomit", 1.0F, 1.0F);
		}

		if(this == ModItems.med_schizophrenia) {
		}

		if(this == ModItems.loop_stew) {
			player.addPotionEffect(new PotionEffect(Potion.regeneration.id, 20 * 20, 1));
			player.addPotionEffect(new PotionEffect(Potion.resistance.id, 60 * 20, 2));
			player.addPotionEffect(new PotionEffect(Potion.moveSpeed.id, 60 * 20, 1));
			player.addPotionEffect(new PotionEffect(Potion.damageBoost.id, 20 * 20, 2));
		}
		if(this == ModItems.s_cream) {
			player.addPotionEffect(new PotionEffect(Potion.regeneration.id, 20 * 20, 2));
		}
    }

@Override
	protected void onFoodEaten(ItemStack stack, World world, EntityPlayer player) {
		if(!world.isRemote) {

			VersatileConfig.applyPotionSickness(player, 5);

			if(this == ModItems.pill_iodine) {
				player.removePotionEffect(Potion.blindness.id);
				player.removePotionEffect(Potion.confusion.id);
				player.removePotionEffect(Potion.digSlowdown.id);
				player.removePotionEffect(Potion.hunger.id);
				player.removePotionEffect(Potion.moveSlowdown.id);
				player.removePotionEffect(Potion.poison.id);
				player.removePotionEffect(Potion.weakness.id);
				player.removePotionEffect(Potion.wither.id);
				player.removePotionEffect(HbmPotion.radiation.id);
			}

			if(this == ModItems.plan_c) {
				for(int i = 0; i < 10; i++)
					player.attackEntityFrom(rand.nextBoolean() ? ModDamageSource.euthanizedSelf : ModDamageSource.euthanizedSelf2, 1000);
			}

			if(this == ModItems.pill_red) {
				player.addPotionEffect(new PotionEffect(HbmPotion.death.id, 60 * 60 * 20, 0));
			}

			if(this == ModItems.radx) {
				player.addPotionEffect(new PotionEffect(HbmPotion.radx.id, 3 * 60 * 20, 0));
			}

			if(this == ModItems.siox) {
				HbmLivingProps.setAsbestos(player, 0);
				HbmLivingProps.setBlackLung(player, Math.min(HbmLivingProps.getBlackLung(player), HbmLivingProps.maxBlacklung / 5));
			}

			if(this == ModItems.pill_herbal) {
				HbmLivingProps.setAsbestos(player, 0);
				HbmLivingProps.setBlackLung(player, Math.min(HbmLivingProps.getBlackLung(player), HbmLivingProps.maxBlacklung / 5));
				HbmLivingProps.incrementRadiation(player, -100F);

				player.addPotionEffect(new PotionEffect(Potion.confusion.id, 10 * 20, 0));
				player.addPotionEffect(new PotionEffect(Potion.weakness.id, 10 * 60 * 20, 2));
				player.addPotionEffect(new PotionEffect(Potion.digSlowdown.id, 10 * 60 * 20, 2));
				player.addPotionEffect(new PotionEffect(Potion.poison.id, 5 * 20, 2));

				PotionEffect eff = new PotionEffect(HbmPotion.potionsickness.id, 10 * 60 * 20);
				eff.setCurativeItems(new ArrayList());
				player.addPotionEffect(eff);
			}

			if(this == ModItems.xanax) {
				float digamma = HbmLivingProps.getDigamma(player);
				HbmLivingProps.setDigamma(player, Math.max(digamma - 0.5F, 0F));
			}
			if(this == ModItems.animan) {
				int x = (int)MathHelper.floor(player.posX);
				int y = (int)MathHelper.floor(player.posY);
				int z = (int)MathHelper.floor(player.posZ);
				world.playSoundEffect(x, y, z, "hbm:player.oil", 1.0F, 1.0F);

				player.addPotionEffect(new PotionEffect(HbmPotion.run.id, 10 * 20, 0));

				NBTTagCompound nbt = new NBTTagCompound();
				nbt.setString("type", "vomit");
				nbt.setString("mode", "normal");
				nbt.setInteger("count", 25);
				nbt.setInteger("entity", player.getEntityId());
				PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(player.dimension, x, y, z, 25));

				world.playSoundEffect(x, y, z, "hbm:player.vomit", 1.0F, 1.0F);
				player.addPotionEffect(new PotionEffect(Potion.hunger.id, 60, 19));

			}
			if(this == ModItems.chocolate) {
				if(rand.nextInt(25) == 0) {
					player.attackEntityFrom(ModDamageSource.overdose, 1000);
				}
				player.addPotionEffect(new PotionEffect(Potion.digSpeed.id, 60 * 20, 3));
				player.addPotionEffect(new PotionEffect(Potion.moveSpeed.id, 60 * 20, 3));
				player.addPotionEffect(new PotionEffect(Potion.jump.id, 60 * 20, 3));
			}

			if(this == ModItems.fmn) {
				float digamma = HbmLivingProps.getDigamma(player);
				HbmLivingProps.setDigamma(player, Math.min(digamma, 2F));
				player.addPotionEffect(new PotionEffect(Potion.blindness.id, 60, 0));
			}

			if(this == ModItems.five_htp) {
				HbmLivingProps.setDigamma(player, 0);
				player.addPotionEffect(new PotionEffect(HbmPotion.stability.id, 10 * 60 * 20, 0));
			}
		}
	}

