				player.addPotionEffect(new PotionEffect(Potion.confusion.id, 10 * 20, 0));
				player.addPotionEffect(new PotionEffect(Potion.weakness.id, 10 * 60 * 20, 2));
				player.addPotionEffect(new PotionEffect(Potion.digSlowdown.id, 10 * 60 * 20, 2));
				player.addPotionEffect(new PotionEffect(Potion.poison.id, 5 * 20, 2));

				PotionEffect eff = new PotionEffect(HbmPotion.potionsickness.id, 10 * 60 * 20);
				eff.setCurativeItems(new ArrayList());
				player.addPotionEffect(eff);
			}

			if(this == ModItems.xanax) {
				float digamma = HbmLivingProps.getDigamma(player);
				HbmLivingProps.setDigamma(player, Math.max(digamma - 0.5F, 0F));
			}
			if(this == ModItems.animan) {
				int x = (int)MathHelper.floor(player.posX);
				int y = (int)MathHelper.floor(player.posY);
				int z = (int)MathHelper.floor(player.posZ);
				world.playSoundEffect(x, y, z, "hbm:player.oil", 1.0F, 1.0F);

				player.addPotionEffect(new PotionEffect(HbmPotion.run.id, 10 * 20, 0));

				NBTTagCompound nbt = new NBTTagCompound();
				nbt.setString("type", "vomit");
				nbt.setString("mode", "normal");
				nbt.setInteger("count", 25);
				nbt.setInteger("entity", player.getEntityId());
				PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(player.dimension, x, y, z, 25));

				world.playSoundEffect(x, y, z, "hbm:player.vomit", 1.0F, 1.0F);
				player.addPotionEffect(new PotionEffect(Potion.hunger.id, 60, 19));

			}
			if(this == ModItems.chocolate) {
				if(rand.nextInt(25) == 0) {
					player.attackEntityFrom(ModDamageSource.overdose, 1000);
				}
				player.addPotionEffect(new PotionEffect(Potion.digSpeed.id, 60 * 20, 3));
				player.addPotionEffect(new PotionEffect(Potion.moveSpeed.id, 60 * 20, 3));
				player.addPotionEffect(new PotionEffect(Potion.jump.id, 60 * 20, 3));
			}

			if(this == ModItems.fmn) {
				float digamma = HbmLivingProps.getDigamma(player);
				HbmLivingProps.setDigamma(player, Math.min(digamma, 2F));
				player.addPotionEffect(new PotionEffect(Potion.blindness.id, 60, 0));
			}

			if(this == ModItems.five_htp) {
				HbmLivingProps.setDigamma(player, 0);
				player.addPotionEffect(new PotionEffect(HbmPotion.stability.id, 10 * 60 * 20, 0));
			}
		}
	}

public boolean onItemUse(ItemStack stack, EntityPlayer player, World world, int x, int y, int z, int i, float f0, float f1, float f2) {
		if(com.hbm.world.WorldBlockState.read(world, x, y, z).getBlock() != Blocks.snow_layer) {
			if(i == 0) {
				--y;
			}

			if(i == 1) {
				++y;
			}

			if(i == 2) {
				--z;
			}

			if(i == 3) {
				++z;
			}

			if(i == 4) {
				--x;
			}

			if(i == 5) {
				++x;
			}

			if(!com.hbm.world.WorldBlockState.read(world, x, y, z).getBlock().isReplaceable(world, x, y, z)) {
				return false;
			}
		}

		if(!player.canPlayerEdit(x, y, z, i, stack)) {
			return false;
		} else {
			--stack.stackSize;
			world.setBlock(x, y, z, ModBlocks.fluid_duct_neo);

			if(world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z)) instanceof TileEntityPipeBaseNT) {
				((TileEntityPipeBaseNT) world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z))).setType(Fluids.fromID(stack.getItemDamage()));
			}

			world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, ModBlocks.fluid_duct_neo.stepSound.func_150496_b(), (ModBlocks.fluid_duct_neo.stepSound.getVolume() + 1.0F) / 2.0F, ModBlocks.fluid_duct_neo.stepSound.getPitch() * 0.8F);

			return true;
		}
	}

@Override
	public boolean onItemUse(ItemStack stack, EntityPlayer player, World world, int x, int y, int z, int side, float fx, float fy, float fz) {

		Block b = com.hbm.world.WorldBlockState.read(world, x, y, z).getBlock();

		if(b instanceof RBMKBase) {
			RBMKBase rbmk = (RBMKBase) b;

			int[] pos = rbmk.findCore(world, x, y, z);

			if(pos == null)
				return false;

			TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(pos[0], pos[1], pos[2]));

			if(!(te instanceof TileEntityRBMKBase))
				return false;

			TileEntityRBMKBase tile = (TileEntityRBMKBase) te;

			if(tile.hasLid())
				return false;

			RBMKNeutronNode node = (RBMKNeutronNode) NeutronNodeWorld.getNode(world, new BlockPos(te));
			if(node != null)
				node.addLid();

			int meta = RBMKBase.DIR_NORMAL_LID.ordinal();

			if(this == ModItems.rbmk_lid_glass) {
				meta = RBMKBase.DIR_GLASS_LID.ordinal();
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, Blocks.glass.stepSound.func_150496_b(), (Blocks.glass.stepSound.getVolume() + 1.0F) / 2.0F, Blocks.glass.stepSound.getPitch() * 0.8F);
			} else {
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, ModBlocks.concrete_smooth.stepSound.func_150496_b(), (ModBlocks.concrete_smooth.stepSound.getVolume() + 1.0F) / 2.0F, ModBlocks.concrete_smooth.stepSound.getPitch() * 0.8F);
			}

			tile.explodeOnBroken = false;
			world.setBlockMetadataWithNotify(pos[0], pos[1], pos[2], meta + RBMKBase.offset, 3);
			tile.explodeOnBroken = true;
			stack.stackSize--;

			return true;
		}

		return false;
	}

