@Override
	public boolean onItemUse(ItemStack p_77648_1_, EntityPlayer p_77648_2_, World p_77648_3_, int p_77648_4_, int p_77648_5_, int p_77648_6_, int p_77648_7_, float p_77648_8_, float p_77648_9_, float p_77648_10_)
    {
        if (p_77648_3_.isRemote)
        {
            return true;
        }
        else
        {
            if (p_77648_7_ == 0)
            {
                --p_77648_5_;
            }

            if (p_77648_7_ == 1)
            {
                ++p_77648_5_;
            }

            if (p_77648_7_ == 2)
            {
                --p_77648_6_;
            }

            if (p_77648_7_ == 3)
            {
                ++p_77648_6_;
            }

            if (p_77648_7_ == 4)
            {
                --p_77648_4_;
            }

            if (p_77648_7_ == 5)
            {
                ++p_77648_4_;
            }

            if (!p_77648_2_.canPlayerEdit(p_77648_4_, p_77648_5_, p_77648_6_, p_77648_7_, p_77648_1_))
            {
                return false;
            }
            else
            {
                if (com.hbm.world.WorldBlockState.read(p_77648_3_, p_77648_4_, p_77648_5_, p_77648_6_).getBlock().getDefaultState().getMaterial() == Material.AIR)
                {
                    p_77648_3_.playSoundEffect(p_77648_4_ + 0.5D, p_77648_5_ + 0.5D, p_77648_6_ + 0.5D, "fire.ignite", 1.0F, itemRand.nextFloat() * 0.4F + 0.8F);
                    p_77648_3_.setBlock(p_77648_4_, p_77648_5_, p_77648_6_, Blocks.fire);
                }

                if (!p_77648_2_.capabilities.isCreativeMode)
                {
                    --p_77648_1_.stackSize;
                }

                return true;
            }
        }
    }

@Override
	public boolean onItemUse(ItemStack itemStack, EntityPlayer player, World world, int x, int y, int z, int p_77648_7_, float p_77648_8_, float p_77648_9_, float p_77648_10_)
    {
        if (p_77648_7_ == 0)
        {
            --y;
        }

        if (p_77648_7_ == 1)
        {
            ++y;
        }

        if (p_77648_7_ == 2)
        {
            --z;
        }

        if (p_77648_7_ == 3)
        {
            ++z;
        }

        if (p_77648_7_ == 4)
        {
            --x;
        }

        if (p_77648_7_ == 5)
        {
            ++x;
        }

        if (!player.canPlayerEdit(x, y, z, p_77648_7_, itemStack))
        {
            return false;
        }
        else
        {
            if (world.isAirBlock(x, y, z))
            {
                world.playSoundEffect(x + 0.5D, y + 0.5D, z + 0.5D, "random.break", 1.0F, itemRand.nextFloat() * 0.4F + 0.8F);
                world.setBlock(x, y, z, Blocks.redstone_wire);
            }

            itemStack.damageItem(14, player);
            return true;
        }
    }

@Override
	public void onUpdate(ItemStack stack, World world, Entity entity, int i, boolean b) {
		int j = getAnim(stack);

		if (j > 0) {
			if (j < 30)
				setAnim(stack, j + 1);
			else
				setAnim(stack, 0);

			if (j == 15) {
				world.playSoundAtEntity(entity, "hbm:weapon.b92Reload", 2F, 0.9F);
				setPower(stack, getPower(stack) + 1);

				if(getPower(stack) > 10) {

					setPower(stack, 0);

					if(!world.isRemote) {
						EntityNukeExplosionMK3 ex = EntityNukeExplosionMK3.statFacFleija(world, entity.posX, entity.posY, entity.posZ, 50);
						if(!ex.isDead) {
							world.playSoundEffect(entity.posX, entity.posY, entity.posZ, "random.explode", 100.0f, world.rand.nextFloat() * 0.1F + 0.9F);
							world.spawnEntityInWorld(ex);

							EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(world, 50);
							cloud.posX = entity.posX;
							cloud.posY = entity.posY;
							cloud.posZ = entity.posZ;
							world.spawnEntityInWorld(cloud);
						}
					}
				}
			}
		}

	}

@Override
	public boolean hitEntity(ItemStack stack, EntityLivingBase victim, EntityLivingBase attacker) {

		boolean active = stack.getItemDamage() < stack.getMaxDamage();

		if(active) {

			attacker.world.playSoundEffect(victim.posX, victim.posY, victim.posZ, "mob.zombie.woodbreak", 1.0F, 0.75F + victim.getRNG().nextFloat() * 0.2F);

			if(!attacker.world.isRemote && !victim.isEntityAlive()) {
				int count = Math.min((int)Math.ceil(victim.getMaxHealth() / 3D), 250);

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaburst");
				data.setInteger("count", count * 4);
				data.setDouble("motion", 0.1D);
				data.setString("mode", "blockdust");
				data.setInteger("block", Block.getIdFromBlock(Blocks.redstone_block));
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, victim.posX, victim.posY + victim.height * 0.5, victim.posZ), new TargetPoint(victim.dimension, victim.posX, victim.posY + victim.height * 0.5, victim.posZ, 50));
			}

			if(attacker instanceof EntityPlayer && (((EntityPlayer)attacker).getDisplayName().equals("Tankish") || ((EntityPlayer)attacker).getDisplayName().equals("Tankish020")))
				return true;

			return super.hitEntity(stack, victim, attacker);
		} else {

			if(!attacker.world.isRemote && attacker instanceof EntityPlayer)
				((EntityPlayer)attacker).sendMessage(new TextComponentString("Not enough energy.").setStyle(new Style().setColor(TextFormatting.RED)));
			return false;
		}
	}

public boolean onEntityItemUpdate(EntityItem item) {
		World world = item.world;

		if(item.ticksExisted > 50 * 20 || item.isBurning()) {

			if(!world.isRemote) {

				if(WeaponConfig.dropStar) {

					EntityNukeExplosionMK3 ex = EntityNukeExplosionMK3.statFacFleija(world, item.posX, item.posY, item.posZ, 100);
					if(!ex.isDead) {
						world.playSoundEffect(item.posX, item.posY, item.posZ, "random.explode", 100.0F, world.rand.nextFloat() * 0.1F + 0.9F);
						world.spawnEntityInWorld(ex);

						EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(world, 100);
						cloud.posX = item.posX;
						cloud.posY = item.posY;
						cloud.posZ = item.posZ;
						world.spawnEntityInWorld(cloud);
					}
				}

				item.setDead();
			}
		}

		int randy = (50 * 20) - item.ticksExisted;

		if(randy < 1)
			randy = 1;

		if(item.world.rand.nextInt(50 * 20) >= randy)
			world.spawnParticle("reddust", item.posX + item.world.rand.nextGaussian() * item.width / 2, item.posY + item.world.rand.nextGaussian() * item.height, item.posZ + item.world.rand.nextGaussian() * item.width / 2, 0.0, 0.0, 0.0);
		else
			world.spawnParticle("smoke", item.posX + item.world.rand.nextGaussian() * item.width / 2, item.posY + item.world.rand.nextGaussian() * item.height, item.posZ + item.world.rand.nextGaussian() * item.width / 2, 0.0, 0.0, 0.0);

		if(randy < 100)
			world.spawnParticle("lava", item.posX + item.world.rand.nextGaussian() * item.width / 2, item.posY + item.world.rand.nextGaussian() * item.height, item.posZ + item.world.rand.nextGaussian() * item.width / 2, 0.0, 0.0, 0.0);

		return false;
	}

public static void gib(EntityLivingBase entity) {
		if(entity instanceof EntityOcelot) return;

		int type = 0;
		if(entity instanceof EntitySlime) type = 1;
		if(entity instanceof EntityMagmaCube) type = 1;
		if(entity instanceof EntityCreeper) type = 1;
		if(entity instanceof EntityGolem) type = 2;
		if(entity instanceof EntityIronGolem) type = 2;
		if(entity instanceof EntityCyberCrab) type = 2;
		if(entity instanceof EntityTeslaCrab) type = 2;
		if(entity instanceof EntityTaintCrab) type = 2;
		if(entity instanceof EntityBlaze) type = 2;
		if(entity instanceof EntityFBIDrone) type = 2;
		if(entity instanceof EntityRADBeast) type = 2;
		if(entity instanceof EntityUFO) type = 2;
		if(entity instanceof EntityBOTPrimeBase) type = 2;

		SkeletonCreator.composeEffectGib(entity.world, entity, 0.25F);

		if(entity instanceof EntitySkeleton) return;

		NBTTagCompound vdat = new NBTTagCompound();
		vdat.setString("type", "giblets");
		vdat.setInteger("ent", entity.getEntityId());
		vdat.setInteger("gibType", type);
		PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, entity.posX, entity.posY + entity.height * 0.5, entity.posZ), new TargetPoint(entity.dimension, entity.posX, entity.posY + entity.height * 0.5, entity.posZ, 150));
		entity.world.playSoundEffect(entity.posX, entity.posY, entity.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + entity.getRNG().nextFloat() * 0.2F);
	}

public static void deciderAutoRefire(ItemStack stack, LambdaContext ctx, GunState lastState, int recIndex, int gunIndex, BooleanSupplier refireCondition) {

		if(lastState == GunState.COOLDOWN) {

			EntityLivingBase entity = ctx.entity;
			EntityPlayer player = ctx.getPlayer();
			GunConfig cfg = ctx.config;
			Receiver rec = cfg.getReceivers(stack)[recIndex];

			//if the gun supports re-fire (i.e. if it's an auto)
			if(rec.getRefireOnHold(stack) && refireCondition.getAsBoolean()) {
				//if there's a bullet loaded, fire again
				if(rec.getCanFire(stack).apply(stack, ctx)) {
					rec.getOnFire(stack).accept(stack, ctx);
					ItemGunBaseNT.setState(stack, gunIndex, GunState.COOLDOWN);
					ItemGunBaseNT.setTimer(stack, gunIndex, rec.getDelayAfterFire(stack));

					if(rec.getFireSound(stack) != null) entity.world.playSoundEffect(entity.posX, entity.posY, entity.posZ, rec.getFireSound(stack), rec.getFireVolume(stack), rec.getFirePitch(stack));

					int remaining = rec.getRoundsPerCycle(stack) - 1;
					for(int i = 0; i < remaining; i++) if(rec.getCanFire(stack).apply(stack, ctx)) rec.getOnFire(stack).accept(stack, ctx);
				//if not, check if dry firing is allowed for refires
				} else if(rec.getDoesDryFireAfterAuto(stack)) {
					//if refire after dry is allowed, switch to COOLDOWN which will trigger a refire, otherwise switch to DRAWING
					ItemGunBaseNT.setState(stack, gunIndex, rec.getRefireAfterDry(stack) ? GunState.COOLDOWN : GunState.DRAWING);
					ItemGunBaseNT.setTimer(stack, gunIndex, rec.getDelayAfterDryFire(stack));
					ItemGunBaseNT.playAnimation(player, stack, GunAnimation.CYCLE_DRY, gunIndex);
				//if not, revert to idle
				} else {
					ItemGunBaseNT.setState(stack, gunIndex, GunState.IDLE);
					ItemGunBaseNT.setTimer(stack, gunIndex, 0);
				}
			//if not, go idle
			} else {

				//reload on empty, only for non-refiring guns
				if(rec.getReloadOnEmpty(stack) && rec.getMagazine(stack).getAmount(stack, ctx.inventory) <= 0) {
					ItemGunBaseNT.setIsAiming(stack, false);
					IMagazine mag = rec.getMagazine(stack);

					if(mag.canReload(stack, ctx.inventory)) {
						int loaded = mag.getAmount(stack, ctx.inventory);
						mag.setAmountBeforeReload(stack, loaded);
						ItemGunBaseNT.setState(stack, ctx.configIndex, GunState.RELOADING);
						ItemGunBaseNT.setTimer(stack, ctx.configIndex, rec.getReloadBeginDuration(stack) + (loaded <= 0 ? rec.getReloadCockOnEmptyPre(stack) : 0));
						ItemGunBaseNT.playAnimation(player, stack, GunAnimation.RELOAD, ctx.configIndex);
					} else {
						ItemGunBaseNT.setState(stack, gunIndex, GunState.IDLE);
						ItemGunBaseNT.setTimer(stack, gunIndex, 0);
					}

				} else {
					ItemGunBaseNT.setState(stack, gunIndex, GunState.IDLE);
					ItemGunBaseNT.setTimer(stack, gunIndex, 0);
				}
			}
		}
	}

public static void clickReceiver(ItemStack stack, LambdaContext ctx, int receiver) {

		EntityLivingBase entity = ctx.entity;
		EntityPlayer player = ctx.getPlayer();
		Receiver rec = ctx.config.getReceivers(stack)[receiver];
		int index = ctx.configIndex;
		GunState state = ItemGunBaseNT.getState(stack, index);

		if(state == GunState.IDLE) {

			if(rec.getCanFire(stack).apply(stack, ctx)) {
				rec.getOnFire(stack).accept(stack, ctx);

				if(rec.getFireSound(stack) != null)
					entity.world.playSoundEffect(entity.posX, entity.posY, entity.posZ, rec.getFireSound(stack), rec.getFireVolume(stack), rec.getFirePitch(stack));

				int remaining = rec.getRoundsPerCycle(stack) - 1;
				for(int i = 0; i < remaining; i++) if(rec.getCanFire(stack).apply(stack, ctx)) rec.getOnFire(stack).accept(stack, ctx);

				ItemGunBaseNT.setState(stack, index, GunState.COOLDOWN);
				ItemGunBaseNT.setTimer(stack, index, rec.getDelayAfterFire(stack));
			} else {

				if(rec.getDoesDryFire(stack)) {
					ItemGunBaseNT.playAnimation(player, stack, GunAnimation.CYCLE_DRY, index);
					ItemGunBaseNT.setState(stack, index, rec.getRefireAfterDry(stack) ? GunState.COOLDOWN : GunState.DRAWING);
					ItemGunBaseNT.setTimer(stack, index, rec.getDelayAfterDryFire(stack));
				}
			}
		}

		if(state == GunState.RELOADING) {
			ItemGunBaseNT.setReloadCancel(stack, true);
		}
	}

