				}
				if(b.getDefaultState().getMaterial() == Material.FIRE) bullet.world.playSoundEffect(bullet.posX, bullet.posY, bullet.posZ, "random.fizz", 1.0F, 1.5F + bullet.world.rand.nextFloat() * 0.5F);
			}
		}
	};

	public static Consumer<Entity> LAMBDA_SAND_UPDATE = (bullet) -> {
		if(bullet.world.isRemote) {
			NBTTagCompound data = new NBTTagCompound();
			data.setString("type", "vanillaExt");
