			if(this.prevErector != this.erector) this.erectorMoving = true;

			if(prevLiftMoving && !this.liftMoving) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:door.wgh_stop", 2F, 1F);
			if(prevErectorMoving && !this.erectorMoving) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:door.garage_stop", 2F, 1F);

		} else {
			this.prevLift = this.lift;
			this.prevErector = this.erector;

			if(this.sync > 0) {
				this.lift = this.lift + ((this.syncLift - this.lift) / (float) this.sync);
				this.erector = this.erector + ((this.syncErector - this.erector) / (float) this.sync);
				--this.sync;
			} else {
				this.lift = this.syncLift;
				this.erector = this.syncErector;
			}

			if(this.liftMoving) {
				if(this.audioLift == null || !this.audioLift.isPlaying()) {
					this.audioLift = MainRegistry.proxy.getLoopedSound("hbm:door.wgh_start", this.pos.getX(), this.pos.getY(), this.pos.getZ(), 0.75F, 25F, 1.0F, 5);
					this.audioLift.startSound();
				}
				this.audioLift.keepAlive();
			} else {
				if(this.audioLift != null) {
					this.audioLift.stopSound();
					this.audioLift = null;
				}
			}

			if(this.erectorMoving) {
				if(this.audioErector == null || !this.audioErector.isPlaying()) {
					this.audioErector = MainRegistry.proxy.getLoopedSound("hbm:door.garage_move", this.pos.getX(), this.pos.getY(), this.pos.getZ(), 1.5F, 25F, 1.0F, 5);
					this.audioErector.startSound();
				}
				this.audioErector.keepAlive();
			} else {
				if(this.audioErector != null) {
					this.audioErector.stopSound();
					this.audioErector = null;
				}
			}

			if(this.erected && (this.formFactor == MissileFormFactor.HUGE.ordinal() || this.formFactor == MissileFormFactor.ATLAS.ordinal()) && this.tanks[1].getFill() > 0) {
				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "tower");
				data.setFloat("lift", 0F);
				data.setFloat("base", 0.5F);
				data.setFloat("max", 2F);
				data.setInteger("life", 70 + this.world.rand.nextInt(30));
				data.setDouble("posX", this.pos.getX() + 0.5 + this.world.rand.nextGaussian() * 0.5);
				data.setDouble("posZ", this.pos.getZ() + 0.5 + this.world.rand.nextGaussian() * 0.5);
				data.setDouble("posY", this.pos.getY() + 2);
				data.setBoolean("noWind", true);
				data.setFloat("alphaMod", 2F);
				data.setFloat("strafe", 0.05F);
				for(int i = 0; i < 3; i++) MainRegistry.proxy.effectNT(data);
			}

			List<EntityMissileBaseNT> entities = this.world.getEntitiesWithinAABB(EntityMissileBaseNT.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY(), this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 10, this.pos.getZ() + 1.5));

			if(!entities.isEmpty()) {
				for(int i = 0; i < 15; i++) {

					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10);
					if(this.world.rand.nextBoolean()) dir = dir.getOpposite();
					float moX = (float) (this.world.rand.nextGaussian() * 0.15F + 0.75) * dir.offsetX;
					float moZ = (float) (this.world.rand.nextGaussian() * 0.15F + 0.75) * dir.offsetZ;

					NBTTagCompound data = new NBTTagCompound();
					data.setDouble("posX", this.pos.getX() + 0.5);
					data.setDouble("posY", this.pos.getY() + 0.25);
					data.setDouble("posZ", this.pos.getZ() + 0.5);
					data.setString("type", "launchSmoke");
					data.setDouble("moX", moX);
					data.setDouble("moY", 0);
					data.setDouble("moZ", moZ);
					MainRegistry.proxy.effectNT(data);
				}
			}
		}

		super.update();
	}

public BombReturnCode launch() {

		if(slots[1] != null && slots[2] != null && slots[3] != null && this.missileLoaded) {
			if(slots[1].getItem() == ModItems.launch_code && slots[2].getItem() == ModItems.launch_key) {
				if(slots[3] != null && slots[3].getItem() instanceof IDesignatorItem) {
					IDesignatorItem designator = (IDesignatorItem) slots[3].getItem();

					if(!designator.isReady(this.world, slots[3], this.pos.getX(), this.pos.getY(), this.pos.getZ())) return BombReturnCode.ERROR_MISSING_COMPONENT;

					Vec3d coords = designator.getCoords(this.world, slots[3], this.pos.getX(), this.pos.getY(), this.pos.getZ());
					int targetX = (int) Math.floor(coords.x);
					int targetZ = (int) Math.floor(coords.z);

					EntityMissileDoomsdayRusted missile = new EntityMissileDoomsdayRusted(this.world, this.pos.getX() + 0.5F, this.pos.getY() + 1F, this.pos.getZ() + 0.5F, targetX, targetZ);
					this.world.spawnEntityInWorld(missile);
					TrackerUtil.setTrackingRange(this.world, missile, 500);
					this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY(), this.pos.getZ() + 0.5, "hbm:weapon.missileTakeOff", 2.0F, 1.0F);
					this.missileLoaded = false;
					this.decrStackSize(1, 1);
					this.markDirty();

					return BombReturnCode.LAUNCHED;
				}
			}
		}

		return BombReturnCode.ERROR_MISSING_COMPONENT;
	}

public void launchTo(int tX, int tZ) {

		this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.missileTakeOff", 10.0F, 1.0F);

		ItemCustomMissilePart chip = (ItemCustomMissilePart) Item.getItemById(ItemCustomMissile.readFromNBT(slots[0], "chip"));
		float c = (Float)chip.attributes[0];
		float f = 1.0F;

		if(getStruct(slots[0]).fins != null) {
			ItemCustomMissilePart fins = (ItemCustomMissilePart) Item.getItemById(ItemCustomMissile.readFromNBT(slots[0], "stability"));
			f = (Float) fins.attributes[0];
		}

		Vec3d target = new Vec3d(this.pos.getX() - tX, 0, this.pos.getZ() - tZ);
		target = new Vec3d(target.x * c * f, target.y, target.z * c * f);

		target = target.rotateYaw(this.world.rand.nextFloat() * 360);

		EntityMissileCustom missile = new EntityMissileCustom(this.world, this.pos.getX() + 0.5F, this.pos.getY() + 2.5F, this.pos.getZ() + 0.5F, tX + (int)target.x, tZ + (int)target.z, getStruct(slots[0]));
		this.world.spawnEntityInWorld(missile);

		subtractFuel();

		slots[0] = null;
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.loaded = this.isLoaded();

			if(!loaded) {
				started = false;
			}

			if(started) {
				timer--;

				if(timer % 20 == 0)
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.fstbmbPing", 5.0F, 1.0F);
			}

			if(timer <= 0) {
				explode();
			}

			networkPackNT(250);
		}
	}

public void handleButtonPacket(int value, int meta) {

		if(meta == 0 && this.isLoaded()) {
			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.fstbmbStart", 5.0F, 1.0F);
			started = true;
		}

		if(meta == 1)
			timer = value * 20;
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(comTimer == 360) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.hornNearSingle", 10F, 1F);
			if(comTimer == 280) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.hornFarSingle", 10000F, 1F);
			if(comTimer == 220) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.hornNearDual", 10F, 1F);
			if(comTimer == 100) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.hornFarDual", 10000F, 1F);

			if(comTimer == 0) {
				List<EntityPlayer> players = this.world.getEntitiesWithinAABB(EntityPlayer.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 10, this.pos.getY() - 10, this.pos.getZ() - 10, this.pos.getX() + 11, this.pos.getY() + 11, this.pos.getZ() + 11));
				EntityPlayer first = players.isEmpty() ? null : players.get(0);
				boolean bonus = first == null ? false : (HbmPlayerProps.getData(first).reputation >= 10);
				EntityBobmazon shuttle = new EntityBobmazon(this.world);
				shuttle.posX = this.pos.getX() + 0.5 + this.world.rand.nextGaussian() * 10;
				shuttle.posY = 300;
				shuttle.posZ = this.pos.getZ() + 0.5 + this.world.rand.nextGaussian() * 10;
				ItemStack payload = ItemKitCustom.create("Supplies", null, 0xffffff, 0x008000,
						DictFrame.fromOne(ModItems.circuit, EnumCircuitType.BASIC, 4 + this.world.rand.nextInt(4)),
						DictFrame.fromOne(ModItems.circuit, EnumCircuitType.ADVANCED, 4 + this.world.rand.nextInt(2)),
						bonus ? new ItemStack(ModItems.gem_alexandrite) : new ItemStack(Items.DIAMOND, 6 + this.world.rand.nextInt(6)),
						new ItemStack(Blocks.RED_FLOWER));
				shuttle.payload = payload;

				this.world.spawnEntityInWorld(shuttle);
			}

			if(comTimer >= 0) {
				comTimer--;
			}

			networkPackNT(250);
		}
	}

