@SuppressWarnings("incomplete-switch")
	private void trigger() {

		Trap trap = Trap.get(this.getBlockMetadata());

		switch(trap) {
		case FALLING_ROCKS:
			for(int x = 0; x < 3; x++) {
				for(int z = 0; z < 3; z++) {
					EntityRubble rubble = new EntityRubble(this.world, this.pos.getX() - 0.5 + x, this.pos.getY() - 0.5, this.pos.getZ() - 0.5 + z);
					rubble.setMetaBasedOnBlock(ModBlocks.reinforced_stone, 0);
					this.world.spawnEntityInWorld(rubble);
				}
			}
			break;
		case ARROW:
			EntityArrow arrow = new EntityArrow(this.world);
			arrow.setPosition(this.pos.getX() + 0.5 + dir.offsetX, this.pos.getY() + 0.5, this.pos.getZ() + 0.5 + dir.offsetZ);
			arrow.motionX = dir.offsetX;
			arrow.motionZ = dir.offsetZ;
			this.world.spawnEntityInWorld(arrow);
			break;
		case FLAMING_ARROW:
			EntityArrow farrow = new EntityArrow(this.world);
			farrow.setPosition(this.pos.getX() + 0.5 + dir.offsetX, this.pos.getY() + 0.5, this.pos.getZ() + 0.5 + dir.offsetZ);
			farrow.motionX = dir.offsetX;
			farrow.motionZ = dir.offsetZ;
			farrow.setFire(60);
			this.world.spawnEntityInWorld(farrow);
			break;
		case PILLAR:
			for(int i = 0; i < 3; i++)
				this.world.setBlock(this.pos.getX(), this.pos.getY() - 1 - i, this.pos.getZ(), ModBlocks.concrete_pillar);
			break;
		case POISON_DART:
			//TBI
			break;
		case ZOMBIE:
			EntityZombie zombie = new EntityZombie(this.world);
			zombie.setPosition(this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5);
			switch(this.world.rand.nextInt(3)) {
			case 0: zombie.setCurrentItemOrArmor(0, new ItemStack(ModItems.chernobylsign)); break;
			case 1: zombie.setCurrentItemOrArmor(0, new ItemStack(ModItems.cobalt_sword)); break;
			case 2: zombie.setCurrentItemOrArmor(0, new ItemStack(ModItems.cmb_hoe)); break;
			}
			zombie.setEquipmentDropChance(0, 1.0F);
			this.world.spawnEntityInWorld(zombie);
			break;
		case SPIDERS:
			for(int i = 0; i < 3; i++) {
				EntityCaveSpider spider = new EntityCaveSpider(this.world);
				spider.setPosition(this.pos.getX() + 0.5, this.pos.getY() - 1, this.pos.getZ() + 0.5);
				this.world.spawnEntityInWorld(spider);
			}
			break;
		}

		this.world.playSoundEffect(this.pos.getX() + 0.5D, this.pos.getY() + 0.5D, this.pos.getZ() + 0.5D, "random.click", 0.3F, 0.6F);
		this.world.setBlock(this.pos.getX(), this.pos.getY(), this.pos.getZ(), ModBlocks.brick_jungle);
	}

public void open() {
		if(state == 0) {
	    	PacketDispatcher.wrapper.sendToAllAround(new TEVaultPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), isOpening, state, 1, 0), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 250));
			isOpening = true;
			state = 1;

			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.reactorStart", 0.5F,
					0.75F);
		}
	}

public void finishOpen() {
		state = 2;

		this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.reactorStop", 0.5F,
				1.0F);
	}

public void close() {
		if(state == 2) {
	    	PacketDispatcher.wrapper.sendToAllAround(new TEVaultPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), isOpening, state, 1, 0), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 250));
			isOpening = false;
			state = 1;

			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.reactorStart", 0.5F,
					0.75F);
		}
	}

public void finishClose() {
		state = 0;

		this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.reactorStop", 0.5F,
				1.0F);
	}

@Override
	public void update() {

		ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata()).getOpposite();

		if(!this.world.isRemote) {
			this.trySubscribe(this.world, this.pos.getX() + dir.offsetX, this.pos.getY(), this.pos.getZ() + dir.offsetZ, dir);

			players = this.world.getEntitiesWithinAABB(EntityPlayer.class, AxisAlignedBB.getBoundingBox(this.pos.getX() + 0.5, this.pos.getY(), this.pos.getZ() + 0.5, this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5).expand(0.5, 0.0, 0.5));

			charge = 0;

			for(EntityPlayer player : players) {

				for(int i = 0; i < 5; i++) {

					ItemStack stack = player.getEquipmentInSlot(i);

					if(stack != null && stack.getItem() instanceof IBatteryItem) {
						IBatteryItem battery = (IBatteryItem) stack.getItem();
						charge += Math.min(battery.getMaxCharge(stack) - battery.getCharge(stack), battery.getChargeRate(stack));
					}
				}
			}

			particles = lastOp > 0;

			if(particles) {

				lastOp--;

				if(this.world.getTotalWorldTime() % 20 == 0)
					this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5, "random.fizz", 0.2F, 0.5F);
			}

			networkPackNT(50);
		}

		lastUsingTicks = usingTicks;

		if((charge > 0 || particles) && usingTicks < delay) {
			usingTicks++;
			if(usingTicks == 2)
				this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5, "tile.piston.out", 0.5F, 0.5F);
		}
		if((charge <= 0 && !particles) && usingTicks > 0) {
			usingTicks--;
			if(usingTicks == 4)
				this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5, "tile.piston.in", 0.5F, 0.5F);
		}

		if(particles) {
			Random rand = this.world.rand;
			this.world.spawnParticle("magicCrit",
