public void process() {

		List<EntityMovingItem> items = this.world.getEntitiesWithinAABB(EntityMovingItem.class, AxisAlignedBB.getBoundingBox(this.pos.getX(), this.pos.getY() + 1, this.pos.getZ(), this.pos.getX() + 1, this.pos.getY() + 1.5, this.pos.getZ() + 1));

		for(EntityMovingItem item : items) {
			ItemStack stack = item.getItemStack();
			ItemStack output = PressRecipes.getOutput(stack, slots[0]);

			if(output != null && stack.stackSize == 1) {
				item.setDead();
				EntityMovingItem out = new EntityMovingItem(this.world);
				out.setPosition(item.posX, item.posY, item.posZ);
				out.setItemStack(output.copy());
				this.world.spawnEntityInWorld(out);
			}
		}

		this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.pressOperate", getVolume(1.5F), 1.0F);

		if(slots[0].getMaxDamage() != 0) {
			slots[0].setItemDamage(slots[0].getItemDamage() + 1);
			if(slots[0].getItemDamage() >= slots[0].getMaxDamage()) {
				slots[0] = null;
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.prevConsumption = this.consumption;
			this.consumption = 0;

			int chunkX = this.pos.getX() >> 4;
			int chunkZ = this.pos.getZ() >> 4;

			meltdownTick = false;

			lastTickValid = this.world.getChunkProvider().chunkExists(chunkX, chunkZ) &&
					this.world.getChunkProvider().chunkExists(chunkX + 1, chunkZ + 1) &&
					this.world.getChunkProvider().chunkExists(chunkX + 1, chunkZ - 1) &&
					this.world.getChunkProvider().chunkExists(chunkX - 1, chunkZ + 1) &&
					this.world.getChunkProvider().chunkExists(chunkX - 1, chunkZ - 1);

			if(lastTickValid && heat > 0 && heat >= field) {

				int fill = tanks[0].getFill() + tanks[1].getFill();
				int max = tanks[0].getMaxFill() + tanks[1].getMaxFill();
				int mod = heat * 10;

				int size = Math.max(Math.min(fill * mod / max, 1000), 50);

				boolean canExplode = true;
				Iterator<Entry<ATEntry, Long>> it = EntityNukeExplosionMK3.at.entrySet().iterator();
				while(it.hasNext()) {
					Entry<ATEntry, Long> next = it.next();
					if(next.getValue() < this.world.getTotalWorldTime()) {
						it.remove();
						continue;
					}
					ATEntry entry = next.getKey();
					if(entry.dim != this.world.provider.getDimension())  continue;
					Vec3d vec = new Vec3d(this.pos.getX() + 0.5 - entry.x, this.pos.getY() + 0.5 - entry.y, this.pos.getZ() + 0.5 - entry.z);
					if(vec.length() < 300) {
						canExplode = false;
						break;
					}
				}

				if(canExplode) {

					EntityNukeExplosionMK3 ex = new EntityNukeExplosionMK3(this.world);
					ex.posX = this.pos.getX() + 0.5;
					ex.posY = this.pos.getY() + 0.5;
					ex.posZ = this.pos.getZ() + 0.5;
					ex.destructionRange = size;
					ex.speed = BombConfig.blastSpeed;
					ex.coefficient = 1.0F;
					ex.waste = false;
					this.world.spawnEntityInWorld(ex);

					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "random.explode", 100000.0F, 1.0F);

					EntityCloudFleijaRainbow cloud = new EntityCloudFleijaRainbow(this.world, size);
					cloud.posX = this.pos.getX();
					cloud.posY = this.pos.getY();
					cloud.posZ = this.pos.getZ();
					this.world.spawnEntityInWorld(cloud);

				} else {
					meltdownTick = true;
					ChunkRadiationManager.proxy.incrementRad(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), 100);
				}
			}

			if(slots[0] != null && slots[2] != null && slots[0].getItem() instanceof ItemCatalyst && slots[2].getItem() instanceof ItemCatalyst)
				color = calcAvgHex(
						((ItemCatalyst)slots[0].getItem()).getColor(),
						((ItemCatalyst)slots[2].getItem()).getColor()
				);
			else
				color = 0;

			if(heat > 0)
				radiation();

			networkPackNT(250);

			heat = 0;

			if(lastTickValid && field > 0) {
				field -= 1;
			}

			this.markDirty();
		} else {

			//TODO: sick particle effects
		}

	}

@Override
	public void update() {

		if (!this.world.isRemote) {
			for(ForgeDirection dir : ForgeDirection.VALID_DIRECTIONS) this.trySubscribe(this.world, this.pos.getX() + dir.offsetX, this.pos.getY() + dir.offsetY, this.pos.getZ() + dir.offsetZ, dir);
			this.subscribeToAllAround(tank.getTankType(), this);

			watts = MathHelper.clamp(watts, 1, 100);
			long demand = maxPower * watts / 2000;

			beam = 0;

			if(joules > 0 || prev > 0) {

				if(tank.getFill() >= 20) {
					tank.setFill(tank.getFill() - 20);
				} else {
					this.world.setBlock(this.pos.getX(), this.pos.getY(), this.pos.getZ(), Blocks.FLOWING_LAVA);
					return;
				}
			}

			if(isOn) {

				//i.e. 50,000,000 HE = 10,000 SPK
				//1 SPK = 5,000HE

				if(power >= demand) {
					power -= demand;
					long add = watts * 100;
					joules += add;
				}
				prev = joules;

				if(joules > 0) {

					long out = joules * 95 / 100;

					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());
					for(int i = 1; i <= range; i++) {

						beam = i;

						int x = this.pos.getX() + dir.offsetX * i;
						int y = this.pos.getY() + dir.offsetY * i;
						int z = this.pos.getZ() + dir.offsetZ * i;

						Block block = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();
						TileEntity te = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

						if(block instanceof ILaserable) { ((ILaserable)block).addEnergy(this.world, x, y, z, out, dir); break; }
						if(te instanceof ILaserable) { ((ILaserable)te).addEnergy(this.world, x, y, z, out, dir); break; }
						if(te instanceof TileEntityCore) { out = ((TileEntityCore)te).burn(out); continue; }

						Block b = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();

						if(!b.isAir(this.world, x, y, z)) {

							if(b.getDefaultState().getMaterial().isLiquid()) {
								this.world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "random.fizz", 1.0F, 1.0F);
								com.hbm.world.WorldAirRemoval.remove(this.world, x, y, z);
								break;
							}

							float hardness = b.getExplosionResistance(null);
							if(hardness < 6000 && this.world.rand.nextInt(20) == 0) {
								this.world.func_147480_a(x, y, z, false);
							}

							break;
						}
					}


					joules = 0;

					double blx = Math.min(this.pos.getX(), this.pos.getX() + dir.offsetX * beam) + 0.2;
					double bux = Math.max(this.pos.getX(), this.pos.getX() + dir.offsetX * beam) + 0.8;
					double bly = Math.min(this.pos.getY(), this.pos.getY() + dir.offsetY * beam) + 0.2;
					double buy = Math.max(this.pos.getY(), this.pos.getY() + dir.offsetY * beam) + 0.8;
					double blz = Math.min(this.pos.getZ(), this.pos.getZ() + dir.offsetZ * beam) + 0.2;
					double buz = Math.max(this.pos.getZ(), this.pos.getZ() + dir.offsetZ * beam) + 0.8;

					List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(blx, bly, blz, bux, buy, buz));

					for(Entity e : list) {
						e.attackEntityFrom(ModDamageSource.amsCore, 50);
						e.setFire(10);
					}
				}
			} else {
				joules = 0;
				prev = 0;
			}

			this.markDirty();

			this.networkPackNT(250);
		}
	}

@Override
	public void update() {
		if(!this.world.isRemote) {
			for(DirPos pos : getConPos()) trySubscribe(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			for(DirPos pos : getInvPos()) tryLoad(pos.getX(), pos.getY(), pos.getZ(), pos.getDir());

			swarmId = ISatChip.getFreqS(slots[1]);
			swarmCount = CBT_Dyson.count(this.world, swarmId);

			isOperating = !isSpinningDown && power >= getPowerPerTick() && slots[0] != null && slots[0].getItem() == ModItems.swarm_member && swarmId > 0;

			if(isSpinningDown) {
				operatingTime++;

				if(operatingTime > getSpinDownTime()) {
					isSpinningDown = false;
					operatingTime = 0;
				}
			} else if(isOperating) {
				if(operatingTime == 0) {
					float pitch = sunsetOverdrive ? 1.0F : 0.25F;
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY() + 8, this.pos.getZ(), "hbm:misc.spincharge", 1.5F, pitch);
				}

				operatingTime++;
				power -= getPowerPerTick();

				if(operatingTime > getSpinUpTime()) {
					int toLaunch = Math.min(slots[0].stackSize, MEMBERS_PER_LAUNCH);
					CBT_Dyson.launch(this.world, swarmId, toLaunch);

					CBT_Atmosphere atmosphere = CelestialBody.getTrait(this.world, CBT_Atmosphere.class);
					double pressure = atmosphere != null ? atmosphere.getPressure() : 0;
					double scaledPressure = 1.0 - Math.pow(1.0 - pressure, 3);

					float volume = Math.min((float)scaledPressure * 16.0F, 4.0F);

					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset);
					ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

					this.world.playSoundEffect(this.pos.getX() + rot.offsetX * 6, this.pos.getY() + 8, this.pos.getZ() + rot.offsetZ * 6, "hbm:misc.spinshot", volume, 0.9F + this.world.rand.nextFloat() * 0.3F);
					this.world.playSoundEffect(this.pos.getX() + rot.offsetX * 6, this.pos.getY() + 8, this.pos.getZ() + rot.offsetZ * 6, "hbm:misc.spinshot", volume, 1F + this.world.rand.nextFloat() * 0.3F);

					int count = Math.min(20, (int)(pressure * 80));

					double posX = this.pos.getX() + rot.offsetX * 9;
					double posY = this.pos.getY() + 12;
					double posZ = this.pos.getZ() + rot.offsetZ * 9;

					NBTTagCompound data = new NBTTagCompound();
					data.setInteger("count", count);
					data.setString("type", "spinlaunch");
					data.setFloat("scale", 3);
					data.setDouble("moX", dir.offsetX * 10);
					data.setDouble("moY", 10);
					data.setDouble("moZ", dir.offsetZ * 10);
					data.setInteger("maxAge", 10 + count / 2 + this.world.rand.nextInt(5));
					PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(data, posX, posY, posZ), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));

					slots[0].stackSize -= toLaunch;
					if(slots[0].stackSize <= 0) slots[0] = null;

					operatingTime = 0;
					isSpinningDown = true;
				}
			} else {
				operatingTime = 0;
			}

			networkPackNT(250);
		} else {
			float acceleration = sunsetOverdrive ? 2.5F : 0.75F;
			float deceleration = sunsetOverdrive ? 15.0F : 3.0F;
			float resetSpeed = sunsetOverdrive ? 30.0F : 8.0F;

			if(isOperating) {
				speed += acceleration;
				if(speed > 90) speed = 90;
			} else if(speed > 0.1F) {
				speed -= deceleration;
				if(speed < resetSpeed) speed = resetSpeed;
			}

			lastRotation = rotation;
			if(!isOperating && speed <= resetSpeed && rotation > 360 - resetSpeed * 1.5) {
				lastRotation -= 360;
				rotation = 0;
				speed = 0;
			} else {
				rotation += speed;
			}

			if(rotation >= 360) {
				rotation -= 360;
				lastRotation -= 360;
			}

			if(isSpinningDown) {
				payloadTicks++;
			} else {
				payloadTicks = 0;
			}
		}
	}

