				}
			} else if(isOperating) {
				if(operatingTime == 0) {
					float pitch = sunsetOverdrive ? 1.0F : 0.25F;
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY() + 8, this.pos.getZ(), "hbm:misc.spincharge", 1.5F, pitch);
				}

				operatingTime++;
				power -= getPowerPerTick();

				if(operatingTime > getSpinUpTime()) {
					int toLaunch = Math.min(slots[0].stackSize, MEMBERS_PER_LAUNCH);
					CBT_Dyson.launch(this.world, swarmId, toLaunch);

					CBT_Atmosphere atmosphere = CelestialBody.getTrait(this.world, CBT_Atmosphere.class);
					double pressure = atmosphere != null ? atmosphere.getPressure() : 0;
					double scaledPressure = 1.0 - Math.pow(1.0 - pressure, 3);

					float volume = Math.min((float)scaledPressure * 16.0F, 4.0F);

					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset);
					ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

					this.world.playSoundEffect(this.pos.getX() + rot.offsetX * 6, this.pos.getY() + 8, this.pos.getZ() + rot.offsetZ * 6, "hbm:misc.spinshot", volume, 0.9F + this.world.rand.nextFloat() * 0.3F);
					this.world.playSoundEffect(this.pos.getX() + rot.offsetX * 6, this.pos.getY() + 8, this.pos.getZ() + rot.offsetZ * 6, "hbm:misc.spinshot", volume, 1F + this.world.rand.nextFloat() * 0.3F);

					int count = Math.min(20, (int)(pressure * 80));

					double posX = this.pos.getX() + rot.offsetX * 9;
					double posY = this.pos.getY() + 12;
					double posZ = this.pos.getZ() + rot.offsetZ * 9;

					NBTTagCompound data = new NBTTagCompound();
					data.setInteger("count", count);
					data.setString("type", "spinlaunch");
					data.setFloat("scale", 3);
					data.setDouble("moX", dir.offsetX * 10);
					data.setDouble("moY", 10);
					data.setDouble("moZ", dir.offsetZ * 10);
					data.setInteger("maxAge", 10 + count / 2 + this.world.rand.nextInt(5));
					PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(data, posX, posY, posZ), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));

					slots[0].stackSize -= toLaunch;
					if(slots[0].stackSize <= 0) slots[0] = null;

					operatingTime = 0;
					isSpinningDown = true;
				}
			} else {
				operatingTime = 0;
			}

			networkPackNT(250);
		} else {
			float acceleration = sunsetOverdrive ? 2.5F : 0.75F;
			float deceleration = sunsetOverdrive ? 15.0F : 3.0F;
			float resetSpeed = sunsetOverdrive ? 30.0F : 8.0F;

			if(isOperating) {
				speed += acceleration;
				if(speed > 90) speed = 90;
			} else if(speed > 0.1F) {
				speed -= deceleration;
				if(speed < resetSpeed) speed = resetSpeed;
			}

			lastRotation = rotation;
			if(!isOperating && speed <= resetSpeed && rotation > 360 - resetSpeed * 1.5) {
				lastRotation -= 360;
				rotation = 0;
				speed = 0;
			} else {
				rotation += speed;
			}

			if(rotation >= 360) {
				rotation -= 360;
				lastRotation -= 360;
			}

			if(isSpinningDown) {
				payloadTicks++;
			} else {
				payloadTicks = 0;
			}
		}
	}

@SuppressWarnings("incomplete-switch")
	@Override
	@Spaghetti ("What the fuck were you thinking")
	public void update() {

		if(!this.world.isRemote) {

			ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset);
			this.trySubscribe(this.world, this.pos.getX() + dir.offsetX * -5, this.pos.getY() + 1, this.pos.getZ() + dir.offsetZ  * -5, dir.getOpposite());
			this.power = Library.chargeTEFromItems(slots, 0, power, maxPower);

			if(this.isOn && !(this.slots[1] == null)) {

				if(this.slots[1].getItem() instanceof ItemFELCrystal) {

					ItemFELCrystal crystal = (ItemFELCrystal) this.slots[1].getItem();
					this.mode = crystal.wavelength;

				} else { this.mode = EnumWavelengths.NULL; }

			} else { this.mode = EnumWavelengths.NULL; }

			int range = 24;
			boolean silexSpacing = false;

			int req = (int) (powerReq * ((mode.ordinal() == 0) ? 0 : Math.pow(3, mode.ordinal())));

			if(this.isOn && this.mode != EnumWavelengths.NULL && power < req) {
				this.power = 0;
			}

			if(this.isOn && power >= req && this.mode != EnumWavelengths.NULL) {

				int distance = this.distance-1;
				double blx = Math.min(this.pos.getX(), this.pos.getX() + dir.offsetX * distance) + 0.2;
				double bux = Math.max(this.pos.getX(), this.pos.getX() + dir.offsetX * distance) + 0.8;
				double bly = Math.min(this.pos.getY(), 1 + this.pos.getY() + dir.offsetY * distance) + 0.2;
				double buy = Math.max(this.pos.getY(), 1 + this.pos.getY() + dir.offsetY * distance) + 0.8;
				double blz = Math.min(this.pos.getZ(), this.pos.getZ() + dir.offsetZ * distance) + 0.2;
				double buz = Math.max(this.pos.getZ(), this.pos.getZ() + dir.offsetZ * distance) + 0.8;

				List<EntityLivingBase> list = this.world.getEntitiesWithinAABB(EntityLivingBase.class, AxisAlignedBB.getBoundingBox(blx, bly, blz, bux, buy, buz));

				for(EntityLivingBase entity : list) {
					switch(this.mode) {
					case VISIBLE: entity.addPotionEffect(new PotionEffect(Potion.blindness.id, 60 * 60 * 65536, 0));
					case IR:
					case UV: entity.setFire(10); break;
					case GAMMA: ContaminationUtil.contaminate(entity, HazardType.RADIATION, ContaminationType.CREATIVE, 25); break;
					case DRX: ContaminationUtil.applyDigammaData(entity, 0.1F); break;
					}
				}

				power -= req;
				for(int i = 3; i < range; i++) {

					int x = this.pos.getX() + dir.offsetX * i;
					int y = this.pos.getY() + 1;
					int z = this.pos.getZ() + dir.offsetZ * i;

					Block b = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();

					if(!(b.getDefaultState().getMaterial().isOpaque()) && b != Blocks.TNT) {
						this.distance = range;
						silexSpacing = false;
						continue;
					}

					if(b == ModBlocks.machine_silex) {

						TileEntity te = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(x + dir.offsetX, this.pos.getY(), z + dir.offsetZ));

						if(te instanceof TileEntitySILEX) {
							TileEntitySILEX silex = (TileEntitySILEX) te;
							int meta = silex.getBlockMetadata() - BlockDummyable.offset;
							if(rotationIsValid(meta, this.getBlockMetadata() - BlockDummyable.offset) && i >= 5 && silexSpacing == false	) {
								if(silex.mode != this.mode) {
									silex.mode = this.mode;
									this.missingValidSilex = false;
									silexSpacing = true;
									continue;
								} 
							} else {
								MachineSILEX silexBlock = (MachineSILEX)silex.getBlockType();
								silexBlock.breakBlock(this.world, silex.getPos().getX(), silex.getPos().getY(), silex.getPos().getZ(), silexBlock, 0);
								this.world.spawnEntity(new EntityItem(this.world, x + 0.5, y + 0.5, z + 0.5, new ItemStack(Item.getItemFromBlock(ModBlocks.machine_silex))));
							} 
						}

					} else if(b.getDefaultState().getMaterial().isOpaque() || b == Blocks.TNT) {

						this.distance = i;

						if(b.getDefaultState().getMaterial().isLiquid()) {
							this.world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "random.fizz", 1.0F, 1.0F);
							com.hbm.world.WorldAirRemoval.remove(this.world, x, y, z);
							break;
						} 

						float hardness = b.getExplosionResistance(null);
						if(hardness < 75 && this.world.rand.nextInt(5) == 0) {
							this.world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "random.fizz", 1.0F, 1.0F);
							Block block = (this.mode != EnumWavelengths.DRX) ? Blocks.FIRE : (MainRegistry.polaroidID == 11) ? ModBlocks.digamma_matter : ModBlocks.fire_digamma;
							this.world.setBlock(x, y, z, block);
							if(this.mode == EnumWavelengths.DRX)
								this.world.setBlock(x, y-1, z, ModBlocks.ash_digamma);
						}
						break;
					}
				}
			}

			this.networkPackNT(250);
		} else {

			if(power > powerReq * Math.pow(2, mode.ordinal()) && isOn && !(mode == EnumWavelengths.NULL) && distance - 3 > 0) {
				audioDuration += 2;
			} else {
				audioDuration -= 3;
			}

			audioDuration = MathHelper.clamp(audioDuration, 0, 60);

			if(audioDuration > 10) {

				if(audio == null) {
					audio = createAudioLoop();
					audio.startSound();
				} else if(!audio.isPlaying()) {
					audio = rebootAudio(audio);
				}

				audio.updateVolume(getVolume(2F));
				audio.updatePitch((audioDuration - 10) / 100F + 0.5F);

			} else {

				if(audio != null) {
					audio.stopSound();
					audio = null;
				}
			}
		}
	}

