@Override
	public void update() {

		if(!this.world.isRemote) {
			boolean canOperate = false;

			for(int i = 2; i < 6; i++) {
				ForgeDirection dir = ForgeDirection.getOrientation(i);
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

				for(int j = -1; j <= 1; j++) {
					this.sendSmoke(this.pos.getX() + dir.offsetX * 2 + rot.offsetX * j, this.pos.getY(), this.pos.getZ() + dir.offsetZ * 2 + rot.offsetZ * j, dir);
				}
			}

			wasOn = false;

			if(burnTime <= 0) {
				canOperate = breatheAir(0);

				for(int i = 0; i < 2; i++) {
					if(slots[i] != null) {

						int baseTime = getModule().getBurnTime(slots[i]);

						if(baseTime > 0) {
							int fuel = (int) (baseTime * getTimeMult());

							TileEntity below = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(this.pos.getX(), this.pos.getY() - 1, this.pos.getZ()));

							if(below instanceof TileEntityAshpit) {
								TileEntityAshpit ashpit = (TileEntityAshpit) below;
								EnumAshType type = getAshFromFuel(slots[i]);
								if(type == EnumAshType.WOOD) ashpit.ashLevelWood += baseTime;
								if(type == EnumAshType.COAL) ashpit.ashLevelCoal += baseTime;
								if(type == EnumAshType.MISC) ashpit.ashLevelMisc += baseTime;
							}

							this.maxBurnTime = this.burnTime = fuel;
							this.burnHeat = getModule().getBurnHeat(getBaseHeat(), slots[i]);
							slots[i].stackSize--;

							if(slots[i].stackSize == 0) {
								slots[i] = slots[i].getItem().getContainerItem(slots[i]);
							}

							this.wasOn = true;
							break;
						}
					}
				} 
			} else {
				if(this.heatEnergy < getMaxHeat()) {
					// firebox consumes 1mB every 5 ticks, heating oven every tick
					canOperate = breatheAir(this.world.getTotalWorldTime() % (500 / getBaseHeat()) == 0 ? 1 : 0);

					if(canOperate) {
						burnTime--;
						if(this.world.getTotalWorldTime() % 20 == 0) this.pollute(PollutionType.SOOT, PollutionHandler.SOOT_PER_SECOND * 3);
					}
				} else {
					canOperate = breatheAir(0);
				}

				if(canOperate) {
					this.wasOn = true;

					if(this.world.rand.nextInt(15) == 0 && !this.muffled) {
						this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "fire.fire", 1.0F, 0.5F + this.world.rand.nextFloat() * 0.5F);
					}
				}
			}

			if(wasOn) {
				this.heatEnergy = Math.min(this.heatEnergy + this.burnHeat, getMaxHeat());
			} else {
				this.heatEnergy = Math.max(this.heatEnergy - Math.max(this.heatEnergy / 1000, 1), 0);
				if(canOperate) this.burnHeat = 0;
			}

			this.networkPackNT(50);
		} else {
			this.prevDoorAngle = this.doorAngle;
			float swingSpeed = (doorAngle / 10F) + 3;

			if(this.playersUsing > 0) {
				this.doorAngle += swingSpeed;
			} else {
				this.doorAngle -= swingSpeed;
			}

			this.doorAngle = MathHelper.clamp(this.doorAngle, 0F, 135F);

			if(wasOn && this.world.getTotalWorldTime() % 5 == 0) {
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset);
				double x = this.pos.getX() + 0.5 + dir.offsetX;
				double y = this.pos.getY() + 0.25;
				double z = this.pos.getZ() + 0.5 + dir.offsetZ;
				this.world.spawnParticle("flame", x + this.world.rand.nextDouble() * 0.5 - 0.25, y + this.world.rand.nextDouble() * 0.25, z + this.world.rand.nextDouble() * 0.5 - 0.25, 0, 0, 0);
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {
			this.tryPullHeat();

			if(this.world.getTotalWorldTime() % 20 == 0) {
				for(int i = 2; i < 6; i++) {
					ForgeDirection dir = ForgeDirection.getOrientation(i);
					ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

					for(int y = this.pos.getY(); y <= this.pos.getY() + 1; y++) {
						for(int j = -1; j <= 1; j++) {
							if(tank.getFill() > 0) this.sendFluid(tank, this.world, this.pos.getX() + dir.offsetX * 2 + rot.offsetX * j, y, this.pos.getZ() + dir.offsetZ * 2 + rot.offsetZ * j, dir);
							this.sendSmoke(this.pos.getX() + dir.offsetX * 2 + rot.offsetX * j, y, this.pos.getZ() + dir.offsetZ * 2 + rot.offsetZ * j, dir);
						}
					}
				}

				for(int x = this.pos.getX() - 1; x <= this.pos.getX() + 1; x++) {
					for(int z = this.pos.getZ() - 1; z <= this.pos.getZ() + 1; z++) {
						if(tank.getFill() > 0) this.sendFluid(tank, this.world, x, this.pos.getY() + 2, z, ForgeDirection.UP);
						this.sendSmoke(x, this.pos.getY() + 2, z, ForgeDirection.UP);
					}
				}
			}

			this.wasOn = false;

			tank.unloadTank(2, 3, slots);

			if(canSmelt()) {
				int burn = heat / 100;

				if(burn > 0) {
					this.wasOn = true;
					this.progress += burn;
					this.heat -= burn;

					if(progress >= processTime) {
						this.markChanged();
						progress -= this.processTime;

						Pair<ItemStack, FluidStack> pair = CombinationRecipes.getOutput(slots[0]);
						ItemStack out = pair.getKey();
						FluidStack fluid = pair.getValue();

						if(out != null)  {
							if(slots[1] == null) {
								slots[1] = out.copy();
							} else {
								slots[1].stackSize += out.stackSize;
							}
						}

						if(fluid != null) {
							if(tank.getTankType() != fluid.type) {
								tank.setTankType(fluid.type);
							}

							tank.setFill(tank.getFill() + fluid.fill);
						}

						this.decrStackSize(0, 1);
					}

					List<Entity> entities = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY() + 2, this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 4, this.pos.getZ() + 1.5));

					for(Entity e : entities) e.setFire(5);

					if(this.world.getTotalWorldTime() % 10 == 0) this.world.playSoundEffect(this.pos.getX(), this.pos.getY() + 1, this.pos.getZ(), "hbm:weapon.flamethrowerShoot", 0.25F, 0.5F);
					if(this.world.getTotalWorldTime() % 20 == 0) this.pollute(PollutionType.SOOT, PollutionHandler.SOOT_PER_SECOND * 3);
				}
			} else {
				this.progress = 0;
			}

			this.networkPackNT(50);
		} else {

			if(this.wasOn && this.world.rand.nextInt(15) == 0) {
				this.world.spawnParticle("lava", this.pos.getX() + 0.5 + this.world.rand.nextGaussian() * 0.5, this.pos.getY() + 2, this.pos.getZ() + 0.5 + this.world.rand.nextGaussian() * 0.5, 0, 0, 0);
			}
		}
	}

@Override
	public void update() {

		timer++;

		if(timer == 10) {
			timer = 0;
			ticker = check();

			// To update the adjacent comparators
			this.world.notifyBlocksOfNeighborChange(this.pos.getX(), this.pos.getY(), this.pos.getZ(), this.getBlockType());
		}

		if(timer % 5 == 0) {

			if(ticker > 0) {
				if(this.world.rand.nextFloat() > ticker) return;
				List<Integer> list = new ArrayList<Integer>();

				if(ticker < 1) list.add(0);
				if(ticker < 5) list.add(0);
				if(ticker < 10) list.add(1);
				if(ticker > 5 && ticker < 15) list.add(2);
				if(ticker > 10 && ticker < 20) list.add(3);
				if(ticker > 15 && ticker < 25) list.add(4);
				if(ticker > 20 && ticker < 30) list.add(5);
				if(ticker > 25) list.add(6);

				int r = list.get(this.world.rand.nextInt(list.size()));

				if(r > 0) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:item.geiger" + r, 1.0F, 1.0F);

			} else if(this.world.rand.nextInt(50) == 0) {
				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:item.geiger"+ (1 + this.world.rand.nextInt(1)), 1.0F, 1.0F);
			}
		}

	}

