@Override
	public void update() {

		if(!this.world.isRemote) {
			if(!hasRegistered) {
				if(isFacingPrograde()) registerPropulsion();
				hasRegistered = true;
				isOn = false;
			}

			for(DirPos pos : this.getConPos()) {
				this.trySubscribe(this.world, pos);
				this.trySubscribe(coolantTanks[0].getTankType(), this.world, pos);
				this.tryProvide(coolantTanks[1], this.world, pos);
			}

			plasmaEnergySync = plasmaEnergy;

			this.temperature += this.temp_passive_heating;
			if(this.temperature > KELVIN + 20) this.temperature = KELVIN + 20;

			if(this.temperature > this.temperature_target) {
				int cyclesTemp = (int) Math.ceil((Math.min(this.temperature - temperature_target, temp_change_max)) / temp_change_per_mb);
				int cyclesCool = coolantTanks[0].getFill();
				int cyclesHot = coolantTanks[1].getMaxFill() - coolantTanks[1].getFill();
				int cycles = BobMathUtil.min(cyclesTemp, cyclesCool, cyclesHot);

				coolantTanks[0].setFill(coolantTanks[0].getFill() - cycles);
				coolantTanks[1].setFill(coolantTanks[1].getFill() + cycles);
				this.temperature -= this.temp_change_per_mb * cycles;
			}

			if(isOn) {
				soundtime++;

				if(soundtime == 1) {
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:misc.htrfstart", 1.5F, 1F);
				} else if(soundtime > 30) {
					soundtime = 30;
				}
			} else {
				soundtime--;

				if(soundtime == 29) {
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:misc.htrstop", 2.0F, 1F);
				} else if(soundtime <= 0) {
					soundtime = 0;
				}
			}


			// nodespace setup
			if(plasmaNode == null || plasmaNode.expired) {
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - BlockDummyable.offset).getRotation(ForgeDirection.UP);
				plasmaNode = UniNodespace.getNode(this.world, this.pos.getX() + dir.offsetX * -10, this.pos.getY(), this.pos.getZ() + dir.offsetZ * -10, PlasmaNetworkProvider.THE_PROVIDER);

				if(plasmaNode == null) {
					plasmaNode = new GenNode(PlasmaNetworkProvider.THE_PROVIDER,
							new BlockPos(this.pos.getX() + dir.offsetX * -10, this.pos.getY(), this.pos.getZ() + dir.offsetZ * -10))
							.setConnections(new DirPos(this.pos.getX() + dir.offsetX * -11, this.pos.getY(), this.pos.getZ() + dir.offsetZ * -11, dir));

					UniNodespace.createNode(this.world, plasmaNode);
				}
			}

			if(plasmaNode != null && plasmaNode.hasValidNet()) plasmaNode.net.addReceiver(this);


			this.networkPackNT(200);
			this.plasmaEnergy = 0;
		} else {

			if(power >= maxPower || isOn) this.rotorSpeed += 0.125F;
			else this.rotorSpeed -= 0.125F;

			this.rotorSpeed = MathHelper.clamp(this.rotorSpeed, 0F, 15F);

			this.prevRotor = this.rotor;
			this.rotor += this.rotorSpeed;

			if(this.rotor >= 360F) {
				this.rotor -= 360F;
				this.prevRotor -= 360F;
			}

			if(isOn) {
				if(soundtime > 28) {
					if(audio == null) {
						audio = createAudioLoop();
						audio.startSound();
					} else if(!audio.isPlaying()) {
						audio = rebootAudio(audio);
					}

					audio.updateVolume(getVolume(1F));
					audio.keepAlive();
				}

				thrustAmount += 0.01D;
				if(thrustAmount > 1) thrustAmount = 1;
			} else {
				if(audio != null) {
					audio.stopSound();
					audio = null;
				}

				thrustAmount -= 0.01D;
				if(thrustAmount < 0) thrustAmount = 0;
			}
		}
	}

