@Override
	public void update() {

		if(!this.world.isRemote) {

			this.sendingChar = ' ';

			if(this.isSending && this.txChannel.isEmpty()) this.isSending = false;

			if(this.isSending) {

				if(sendingWait > 0) {
					sendingWait--;
				} else {

					String line = txBuffer[sendingLine];

					if(line.length() > sendingIndex) {
						char c = line.charAt(sendingIndex);
						sendingIndex++;
						if(c == pause) {
							sendingWait = 20;
						} else {
							RTTYSystem.broadcast(this.world, this.txChannel, c);
							this.sendingChar = c;
						}
					} else {

						if(sendingLine >= 4) {
							this.isSending = false;
							RTTYSystem.broadcast(this.world, this.txChannel, eot);
							this.sendingLine = 0;
							this.sendingIndex = 0;
						} else {
							RTTYSystem.broadcast(this.world, this.txChannel, eol);
							this.sendingLine++;
							this.sendingIndex = 0;
						}
					}
				}
			}

			if(!this.rxChannel.isEmpty()) {
				RTTYChannel chan = RTTYSystem.listen(this.world, this.rxChannel);

				if(chan != null && chan.signal instanceof Character && (chan.timeStamp > this.world.getTotalWorldTime() - 2 && chan.timeStamp != -1)) {
					char c = (char) chan.signal;

					if(this.deleteOnReceive) {
						this.deleteOnReceive = false;
						for(int i = 0; i < 5; i++) this.rxBuffer[i] = "";
						this.writingLine = 0;
					}

					if(c == eot) {
						if(this.printAfterRx) {
							this.printAfterRx = false;
							this.print();
						}
						this.deleteOnReceive = true;
					} else if(c == eol) {
						if(this.writingLine < 4) this.writingLine++;
						this.markDirty();
					} else if(c == bell) {
						this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "random.orb", 2F, 0.5F);
					} else if(c == print) {
						this.printAfterRx = true;
					} else if(c == clear) {
						for(int i = 0; i < 5; i++) this.rxBuffer[i] = "";
						this.writingLine = 0;
					} else {
						this.rxBuffer[this.writingLine] += c;
						this.markDirty();
					}
				}
			}

			networkPackNT(16);
		}
	}

@Override
	public void updateFiringTick() {

		timer++;

		int delay = mode == MODE_ARTILLERY ? 300 : 40;

		if(timer % delay == 0) {

			ItemStack conf = this.getShellLoaded();

			if(conf != null) {
				cachedCasingConfig = ItemAmmoArty.itemTypes[conf.getItemDamage()].casing;
				this.spawnShell(conf);
				this.conusmeAmmo(ModItems.ammo_arty);
				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.jeremy_fire", 25.0F, 1.0F);
				Vec3d pos = this.getTurretPos();
				com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
				vec.rotateAroundZRad((float) -this.rotationPitch);
				vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));
				this.didJustShoot = true;

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaExt");
				data.setString("mode", "largeexplode");
				data.setFloat("size", 0F);
				data.setByte("count", (byte)5);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, pos.x + vec.x, pos.y + vec.y, pos.z + vec.z), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));
