@Override
	public void updateFiringTick() {

		if(this.tank.getTankType().hasTrait(FT_Flammable.class) && this.tank.getTankType().hasTrait(FT_Liquid.class) && this.tank.getFill() >= 2) {

			FT_Flammable trait = this.tank.getTankType().getTrait(FT_Flammable.class);
			this.tank.setFill(this.tank.getFill() - 2);

			Vec3d pos = this.getTurretPos();
			com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
			vec.rotateAroundZRad((float) -this.rotationPitch);
			vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));

			float damage = Math.min((float) (trait.getHeatEnergy() / 500_000F), 20F);
			EntityBulletBaseMK4 proj = new EntityBulletBaseMK4(this.world, tank.getTankType() == Fluids.BALEFIRE ? XFactoryFlamer.flame_nograv_bf : XFactoryFlamer.flame_nograv, damage, 0.05F, (float) rotationYaw, (float) rotationPitch);
			proj.setPositionAndRotation(pos.x + vec.x, pos.y + vec.y, pos.z + vec.z, proj.rotationYaw, proj.rotationPitch);
			this.world.spawnEntityInWorld(proj);

			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.flamethrowerShoot", 2F, 1F + this.world.rand.nextFloat() * 0.5F);
		}
	}

@Override
	public void updateFiringTick() {

		timer++;

		int delay = 40;

		if(timer % delay == 0) {

			if(this.hasAmmo() && this.tPos != null) {
				this.spawnShell(this.typeLoaded);
				this.ammo--;
				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.rocketFlame", 25.0F, 1.0F);
			}

			if(this.mode == this.MODE_MANUAL && !this.targetQueue.isEmpty()) {
				this.targetQueue.remove(0);
				this.tPos = null;
			}
		}
	}

@Override
	public void update() {

		if(this.world.isRemote) {

			this.lastSpin = this.spin;

			if(this.tPos != null) {
				this.spin += 45;
			}

			if(this.spin >= 360F) {
				this.spin -= 360F;
				this.lastSpin -= 360F;
			}
		} else {

			if(loaded <= 0) {
				BulletConfig conf = this.getFirstConfigLoaded();

				if(conf != null) {
					this.conusmeAmmo(conf.ammo);
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.howard_reload", 4.0F, 1F);
					loaded = 200;
				}
			}
		}

		super.update();
	}

@Override
	public void updateFiringTick() {

		timer++;

		if(loaded > 0 && this.tPos != null) {

			SpentCasing cfg = GunDGKFactory.CASINGDGK;

			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.howard_fire", 4.0F, 0.9F + this.world.rand.nextFloat() * 0.3F);
			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.howard_fire", 4.0F, 1F + this.world.rand.nextFloat() * 0.3F);

			for(int i = 0; i < 2; i++) {
				this.cachedCasingConfig = cfg;
				this.spawnCasing();
			}

			if(timer % 2 == 0) {
				loaded--;

				if(this.world.rand.nextInt(100) + 1 <= WeaponConfig.ciwsHitrate)
					EntityDamageUtil.attackEntityFromIgnoreIFrame(this.target, ModDamageSource.shrapnel, 2F + this.world.rand.nextInt(2));

				Vec3d pos = this.getTurretPos();
				com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
				vec.rotateAroundZRad((float) -this.rotationPitch);
				vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));

				com.hbm.util.Vec3NT hOff = new com.hbm.util.Vec3NT(0, 0.25, 0);
				hOff.rotateAroundZRad((float) -this.rotationPitch);
				hOff.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));

				for(int i = 0; i < 2; i++) {

					if(i == 1) {
						hOff = hOff.scale(-1);
					}

					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "vanillaExt");
					data.setString("mode", "largeexplode");
					data.setFloat("size", 1.5F);
					data.setByte("count", (byte)1);
					PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, pos.x + vec.x + hOff.x, pos.y + vec.y + hOff.y, pos.z + vec.z + hOff.z), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 50));
				}
			}
		}
	}

