@Override
	public void updateFiringTick() {

		long demand = this.getConsumption() * 10;

		if(this.target != null && this.getPower() >= demand) {

			if(_5g && target instanceof EntityPlayer) {
				EntityPlayer living = (EntityPlayer) target;
				living.addPotionEffect(new PotionEffect(HbmPotion.death.id, 30 * 60 * 20, 0, true));
			} else {
				EntityDamageUtil.attackEntityFromIgnoreIFrame(this.target, ModDamageSource.microwave, (this.blackLevel * 10 + this.redLevel + 1F) * 0.25F);
			}

			if(pinkLevel > 0)
				this.target.setFire(this.pinkLevel * 3);

			if(!this.target.isEntityAlive() && this.target instanceof EntityLivingBase) {
				NBTTagCompound vdat = new NBTTagCompound();
				vdat.setString("type", "giblets");
				vdat.setInteger("ent", this.target.getEntityId());
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, this.target.posX, this.target.posY + this.target.height * 0.5, this.target.posZ), new TargetPoint(this.target.dimension, this.target.posX, this.target.posY + this.target.height * 0.5, this.target.posZ, 150));

				if(this.screm)
					com.hbm.sound.WorldSoundEffects.play(this.world, this.target.posX, this.target.posY, this.target.posZ, "hbm:block.screm", 20.0F, 1.0F);
				else
					this.world.playSoundEffect(this.target.posX, this.target.posY, this.target.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
			}

			this.power -= demand;

			this.shot = true;
			this.networkPackNT(250);
			this.shot = false;
		}
	}

@Override
	public void updateFiringTick() {

		if(reload > 0)
			return;

		timer++;

		if(timer > 0 && timer % 10 == 0) {

			BulletConfig conf = this.getFirstConfigLoaded();

			if(conf != null) {
				this.spawnBullet(conf, 30F);
				this.conusmeAmmo(conf.ammo);
				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.richard_fire", 2.0F, 1.0F);
				this.loaded--;

				//if(conf.ammo.equals(new ComparableStack(ModItems.ammo_standard, EnumAmmo.ROCKET_DEMO))) timer = -50;

			} else {
				this.loaded = 0;
			}
		}
	}

@Override
	public void updateFiringTick() {

		timer++;

		if(timer % 10 == 0) {

			BulletConfig conf = this.getFirstConfigLoaded();

			if(conf != null) {
				this.cachedCasingConfig = conf.casing;
				this.spawnBullet(conf, 5F);
				this.conusmeAmmo(conf.ammo);
				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.sentry_fire", 2.0F, 1.0F);

				Vec3d pos = this.getTurretPos();
				com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
				vec.rotateAroundZRad((float) -this.rotationPitch);
				vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));

				Vec3d side = new Vec3d(0.125 * (shotSide ? 1 : -1), 0, 0);
				side = side.rotateYaw((float) -(this.rotationYaw));

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaExt");
				data.setString("mode", "largeexplode");
				data.setFloat("size", 1F);
				data.setByte("count", (byte)1);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, pos.x + vec.x + side.x, pos.y + vec.y, pos.z + vec.z + side.z), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 50));

				if(shotSide) {
					this.didJustShootLeft = true;
				} else {
					this.didJustShootRight = true;
				}
				shotSide = !shotSide;
			}
		}
	}

@Override
	public void updateFiringTick() {

		timer++;

		if(timer % 10 == 0) {

			BulletConfig conf = XFactory9mm.p9_fmj;

			if(conf != null) {

				Vec3d pos = this.getTurretPos();
				Vec3d vec = new Vec3d(0, 0, 0);
				Vec3d side = new Vec3d(0, 0, 0);

				this.cachedCasingConfig = conf.casing;

				if(shotSide) {
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.sentry_fire", 2.0F, 1.0F);
					this.spawnBullet(conf, 5F);

					com.hbm.util.Vec3NT barrel = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
					barrel.rotateAroundZRad((float) -this.rotationPitch);
					barrel.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));
					vec = barrel.toVec3d();

					side = new Vec3d(0.125 * (shotSide ? 1 : -1), 0, 0);
					side = side.rotateYaw((float) -(this.rotationYaw));

				} else {
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.sentry_fire", 2.0F, 0.75F);
					if(usesCasings()) {
						if(this.casingDelay() == 0) {
							spawnCasing();
						} else {
							casingDelay = this.casingDelay();
						}
					}
				}

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaExt");
				data.setString("mode", "largeexplode");
				data.setFloat("size", 1F);
				data.setByte("count", (byte) 1);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, pos.x + vec.x + side.x, pos.y + vec.y, pos.z + vec.z + side.z), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 50));

				if(shotSide) {
					this.didJustShootLeft = true;
				} else {
					this.didJustShootRight = true;
				}
				shotSide = !shotSide;
			}
		}
	}

